string MakeLine(string str)
{
    string s = "";
    if(str.size() < 4)
    {
        return str;
    }
    if(str.size()%2 == 0)
    {
        for(int i = 1; i <= str.size(); i++)
        {
            s += str[i-1];
            if(i%2 == 0 && i != str.size())
                s += "-";
        }
    }
    else
    {
        s += str[0];
        s += str[1];
        s += str[2];
        s += "-";
        for(int i = 1; i <= str.size() - 3; i++)
        {
            s += str[i+2];
            if(i%2 == 0 && i != str.size() - 3)
                s += "-";
        }
    }
    return s;
}

