int gcd(int a,int b)
{
    // O(log(a*b)) GCD calculater
    if(b>a)swap(a,b);
    if(b==0)return a;
    return gcd(b,a%b);
}
void doswaps(int& a,int&b,int q)
{
    int n=a-q*b;
    a=b;
    b=n;
}
int egcd(int a,int b,int& x0,int& y0)
{
    int x1,y1;
    x1=y0=0;
    x0=y1=1;
    int r0=a,r1=b;
    while(r1!=0)
    {
        int q=r0/r1;
        doswaps(x0,x1,q);
        doswaps(y0,y1,q);
        doswaps(r0,r1,q);
    }
    return r0;
}

ll fpow(int b,int p)// fast power
{
    if(p==1)return b;
    ll ret= fpow(b,p/2);
    ret*=ret;
    ret%=mod;
    if(p%2)ret= ret * b % mod;
    return ret%mod;
}
ll fact[N];
void pre(int n)
{
    fact[0]=1;
    for(int i=1; i<n; i++)
    {
        fact[i]= ( fact[i-1] * i);
    }
}
ll ncr(int n,int r)
{
    // n! / (n-r)! * r!
    if(r>n)return 0;
    ll ret= fact[n];
    ll d= fact[n-r];
    d*=fact[r];
    d%=mod;
    return (ret*fpow(d,mod-2))%mod;
}


