typedef long long ll;
typedef long double ld;
using namespace std;
const int N = 1e5 + 10;
ll dp[N] , sz[N] , t[N];
vector<pii> a[N];

bool cmp(pair<pair<ll , ll> , int> x , pair<pair<ll , ll >  , int> y){
    ll p1 = x.F.F , p2 = y.F.F , s1 = x.F.S , s2 = y.F.S;
    return p1 * s2 < p2 * s1;
}

void dfs(int v,int p=-1){
    sz[v]++;
    vector<pair<pair<ll , ll >  , int> > childs;
    for(auto X:a[v]){
        int u = X.F , w = X.S;
        if(u == p)continue;
        dfs(u , v);
        sz[v]+=sz[u];
        t[v]+=t[u] + w;
        dp[v]+=w * sz[u] + dp[u];
        childs.pb({{t[u] + w , sz[u]} , u});
    }
    sort(childs.begin() , childs.end() ,cmp);
    ll tim = 0;
    for(auto X:childs){
        ll p = X.F.F , sz = X.F.S , ind = X.S;
        dp[v]+=(ll)2 * tim * sz;
        tim+=p;
    }
    return ;
}

int main(){
    ios_base::sync_with_stdio(0); cin.tie(0);
    int n; cin>>n;
    for(int i=0;i<n-1;i++){
        int u,v,w; cin>>u>>v>>w;
        a[u].pb({v , w});
        a[v].pb({u , w});
    }
    dfs(1);
    cout<<fixed<<setprecision(12)<<(ld)(dp[1])/(n-1)<<'\n';
}

