ll k1, k2;
ll dp(ll n1, ll n2, int f){
    if(n1 == 0 && n2 == 0) return 1;
    else if (n1 < 0 || n2 < 0) return 0;
    if(mem[n1][n2][f] != -1) return mem[n1][n2][f];

    ll nways = 0;
    if(f != 1){
        for(int i = 1; i <= k1; i++){
            if(n1 - i < 0) break;
            nways += dp(n1 - i, n2, 1);
        }
    }

    if(f != 0){
        for(int i = 1; i <= k2; i++){
            if(n2 - i < 0) break;
            nways += dp(n1, n2- i, 0);
        }
    }

    mem[n1][n2][f] = nways % 100000000;
    return mem[n1][n2][f];

}

