void dijkstra(ll src, vector<ll> *adj, vector<ll> & dis){
    set<pair<ll, ll> > st;

    st.insert({0, src});
    while(!st.empty()){
        auto it=*st.begin();
        st.erase(st.begin());
        ll node=it.ss;
        ll d= it.ff;

        for(int it:adj[node]){
            if(d+1<dis[it]){
                st.erase({dis[it], it});
                dis[it]=d+1;

                st.insert({dis[it], it});
            }
        } 
    }
}

