using namespace std;
const int maxn=1000010;
long long c[10];
int f[maxn];
int prime[maxn];
int vis[maxn];
int d(int x)
{
	int tmp=0;
	while(x)
	{
		tmp+=x%10;
		x/=10;
	}
	return tmp<10?tmp:d(tmp);
}
void init()
{
	memset(vis,0,sizeof(vis));
	f[1]=1;
	int tot=0;
	for(int i=2;i<=1000000;i++)
	{
		if(!vis[i])
		{
			f[i]=2;
			prime[tot++]=i;
		}
		for(int j=0;j<tot;j++)
		{
			if(i*prime[j]>1000000) break;
			vis[i*prime[j]]=1;
			if(i%prime[j]==0) 
			{
				int tmp=i;
				while(tmp%prime[j]==0) tmp/=prime[j];
				f[i*prime[j]]=(f[i/tmp]+1)*f[tmp];
				break;
			}
			else f[i*prime[j]]=f[i]*f[prime[j]];
		}
	}
}
int main()
{
	init();
	int n;
	scanf("%d",&n);
	long long res=0;
	for(int i=1;i<=n;i++)
	{
		c[d(i)]++;
		res+=f[i];
	//	cout<<f[i]<<endl;
	}
	long long ans=0;
	for(int i=0;i<10;i++)
		for(int j=0;j<10;j++)
		{
			long long k=d(i*j),tmp;
			if(i==j) tmp=c[i]*c[i];
			else tmp=c[i]*c[j];
			ans+=tmp*c[k];
		}
	//cout<<res<<" "<<ans<<endl;
	cout<<ans-res<<endl;
	return 0;
}

#include<bits/stdc++.h>
#define LL long long
using namespace std;
vector<int>ve;
LL M;
void qfind(int n)
{
	for (int i = 2; i*i <= n; ++i)
		if (n%i == 0)
		{
			n /= i; ve.push_back(i);
			while (n%i == 0) n /= i;
			qfind(n);
			return;
		}
	if(ve.size()==0||n>*ve.rbegin())ve.push_back(n);
}
LL power(LL x, LL n)
{
	LL ans = 1;
	while (n)
	{
		if (n & 1)ans = ans*x%M;
		x = x*x%M;
		n >>= 1;
	}
	return ans;
}
int main()
{
	string b, n; LL c;
	cin >> b >> n;
	scanf("%lld", &c);
	LL nn = 0, bb = 0;
	M = c;
	for (int i = 0; i< b.length(); ++i)
		bb = (bb * 10 % c + b[i] - '0') % M;
	if (n.length() <= 11)
	{
		for (int i = 0; i<n.length(); ++i)
			nn = nn * 10 + n[i] - '0';
	}

	else
	{
		LL temp = c;
		qfind(c);
		for (int i = 0; i < ve.size(); ++i)
		{
			temp = (temp*(ve[i] - 1)*1.0) / ((ve[i]) * 1.0);	
		}
		nn = 0;
		for (int i = 0; i<n.length(); ++i)
			nn = (nn * 10 % temp + n[i] - '0') % temp;
		nn += temp;
	}
	LL ans1 = (power(bb, nn) - power(bb, nn - 1) + M) % M;
	if (ans1 == 0) ans1 = c;
	 printf("%lld\n", ans1);
	return 0;
}

