int root(int v){
    return c[v] == v ? v : c[v] = root(c[v]);
}

bool join(int a, int b){
    a = root(a), b = root(b);
    if(a == b) return false;
    if(rand() & 1) swap(a, b);
    c[a] = b;
    return true;
}

vector<int> getKeyPos(int* pos, vector<int>* key){
    vector<int> key_pos(m, 0);
    forn(i, k)
        forn(j, sz(key[i]))
            key_pos[key[i][j]] = pos[i];
    return key_pos;
}

vector<int> getColor(int* pos, vector<int>* key){
    vector<int> key_pos = getKeyPos(pos, key);

    init();

    bool was = true;
    while(was){
        was = false;
        forn(i, m){
            int u = e[i].X, v = e[i].Y;
            if(root(u) == root(key_pos[i]) || root(v) == root(key_pos[i])){
                if(join(u, v))
                    was = true;
            }
        }
    }

    vector<int> ans(n);
    map<int, int> clr;
    forn(i, n){
        int cur = root(i);
        if(!clr.count(cur)){
            int val = sz(clr);
            clr[cur] = val;
        }
        ans[i] = clr[cur];
    }
    return ans;
}

