    static class BArrayKColoring {
        public void solve(int testNumber, FastScanner br, PrintWriter pw) {
            int n = br.nextInt();
            int k = br.nextInt();
            Pair[] data = new Pair[n];
            for (int i = 0; i < data.length; i++) {
                data[i] = new Pair(br.nextInt(), i);
            }
            Arrays.sort(data);
            int[] fin = new int[n];
            int curr = 1;
            for (int i = 0; i < n; i++) {
                fin[i] = curr++;
                if (curr == k + 1) {
                    curr = 1;
                }
            }
            int[] ret = new int[n];
            boolean[][] used = new boolean[5001][5001];
            for (int i = 0; i < n; i++) {
                ret[data[i].s] = fin[i];
            }
//        for(int i = 0; i < n; i++){
//            pw.print(ret[i] + " ");
//        }
//        pw.println();
            for (int i = 0; i < n; i++) {
                if (used[data[i].f][fin[i]]) {
                    pw.println("NO");
                    pw.close();
                    return;
                } else {
                    used[data[i].f][fin[i]] = true;
                }
            }
            pw.println("YES");
            for (int i = 0; i < n; i++) {
                pw.print(ret[i] + " ");
            }
            pw.close();
        }

    }

    static class Pair implements Comparable<Pair> {
        public int f;
        public int s;

        public Pair(int f, int s) {
            this.f = f;
            this.s = s;
        }

        public int compareTo(Pair p) {
            return this.f == p.f ? this.s - p.s : this.f - p.f;
        }

        public String toString() {
            return "(" + f + "," + s + ")";
        }

    }

    static class FastScanner {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private FastScanner.SpaceCharFilter filter;

        public FastScanner(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

