                    if (check[N[i]] == 0) {
                        count++;
                    }
                    check[N[i]]++;
                }
                for (int i = d - 1; i < n; i++) {
                    N[i] = in.nextInt() - 1;
                    if (check[N[i]] == 0) {
                        count++;
                    }
                    check[N[i]]++;
                    if (count < mi) {
                        mi = count;
                    }
                    if (check[N[i - d + 1]] == 1) {
                        count--;
                    }
                    check[N[i - d + 1]]--;
                }
                out.println(mi);
                for (int i = n - d + 1; i < n; i++) {
                    check[N[i]]--;
                }
            }
        }
