    public static boolean possible(int[] arr,long total)throws IOException
    {
        int n = arr.length; 

        // Run a loop for printing all 2^n 
        // subsets one by obe 
        for (int i = 0; i < (1<<n); i++) 
        { 
            long sum=0;
            // Print current subset 
            for (int j = 0; j < n; j++) 
                {
                if ((i & (1 << j)) > 0) 
                    sum+=arr[j]; 
                 }
            if(total==2*sum)
            return true;
    }
    return false;
    }
