import java.util.*;

public class HelpFarmer {

    static long find(long x, long y, long z) {
        long A = x + 1;
        long B = y + 2;
        long C = z + 2;

        return A * B * C - x * y * z;
    }

    static void find(long x, long yz, long[] minmax) {
        for (int y = 1; y <= yz / y; y++) {
            if (yz % y == 0) {
                long z = yz / y;
                long ans = find(x, y, z);
                minmax[0] = Math.min(minmax[0], ans);
                minmax[1] = Math.max(minmax[1], ans);
            }
        }
    }

    static long[] solve(long n) {
        long[] minmax = {Long.MAX_VALUE, Long.MIN_VALUE};
        for (long x = 1; x <= n / x; x++) {
            if (n % x == 0) {
                long yz = n / x;
                find(x, yz, minmax);
                find(yz, x, minmax);
            }
        }
        return minmax;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);

        long n = in.nextInt();
        long[] ans = solve(n);
        System.out.println(ans[0] + " " + ans[1]);

        in.close();
        System.exit(0);
    }
}

