            Map.Entry<Long, SegL> lowerE = lower.ceilingEntry(vec.x);
            if(upperE == null || upperE.getValue().side(vec) != -1) {
                System.out.println("NO");
                return;
            }
            if(lowerE == null || lowerE.getValue().side(vec) != -1) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println("YES");

