class TaskA {

    private int n;
    private int[] completeOn;
    private int[] degIn;
    private boolean[][] g;

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        n = in.nextInt();
        completeOn = Utils.readIntArray(in, n);
        degIn = new int[n];
        g = new boolean[n][n];
        for (int i = 0; i < n; ++i) {
            int am = in.nextInt();
            for (int j = 0; j < am; ++j) {
                int x = in.nextInt()-1;
                g[x][i] = true;
                degIn[i]++;
            }
        }
        int res = Integer.MAX_VALUE;
        for (int i = 1; i <= 3; ++i) {
            res = Math.min(res, process(i));
        }
        out.println(res);
    }

    private int process(int cur) {
        boolean[] visited = new boolean[n];
        int cost = 0;
        int[] curDegIn = degIn.clone();
        while (true) {
            boolean finished = true;
            List<Integer> queue = new ArrayList<Integer>();
            for (int i = 0; i < n; ++i) {
                if (!visited[i]) {
                    finished = false;
                    if (curDegIn[i] == 0 && completeOn[i] == cur) {
                        queue.add(i);
                    }
                }
            }
            if (finished) break;
            if (queue.size() == 0) {
                cur++;
                ++cost;
                if (cur == 4) {
                    cur = 1;
                }
                continue;
            }
            for (int x : queue) {
                ++cost;
                visited[x] = true;
                for (int i = 0; i < n; ++i) {
                    if (g[x][i]) {
                        --curDegIn[i];
                    }
                }
            }
        }
        return cost;
    }
}

