/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskB solver = new TaskB();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int A = in.nextInt();
            int B = in.nextInt();
            char[][] puzzle = new char[A][B];
            for (int i = 0; i < A; i++) {
                puzzle[i] = in.next().toCharArray();
            }
            PriorityQueue<piece> ans = new PriorityQueue<>();
            for (int Y = 1; Y <= A; Y++) {
                for (int X = 1; X <= B; X++) {
                    if (A % Y == 0 && B % X == 0) {
                        if (chk(puzzle, Y, X)) {
                            ans.offer(new piece(Y, X));
                        }
                    }
                }
            }
            out.println(ans.size());
            out.println(ans.peek());
        }

        boolean chk(char[][] puzzle, int Y, int X) {
            ArrayList<fullPiece> pieces = new ArrayList<>();
            for (int i = 0; i < puzzle.length; i += Y) {
                for (int j = 0; j < puzzle[0].length; j += X) {
                    fullPiece next = new fullPiece(puzzle, Y, X, i, j);
                    for (fullPiece cur : pieces) {
                        if (next.eq(cur)) return false;
                    }
                    pieces.add(next);
                }
            }
            return true;
        }

    }

    static class piece implements Comparable {
        int y;
        int x;

        piece(int y1, int x1) {
            y = y1;
            x = x1;
        }

        public int compareTo(Object o) {
            piece other = (piece) o;
            int oS = other.x * other.y;
            int S = x * y;
            if (S == oS) {
                return y - other.y;
            }
            return S - oS;
        }

        public String toString() {
            return y + " " + x;
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer stt;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream));
        }

        public String nextLine() {
            try {
                return reader.readLine();
            } catch (IOException e) {
                return null;
            }
        }

        public String next() {
            while (stt == null || !stt.hasMoreTokens()) {
                stt = new StringTokenizer(nextLine());
            }
            return stt.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }

    static class fullPiece {
        char[][] data;

        fullPiece(char[][] puzzle, int Y, int X, int top, int left) {
            data = new char[Y][X];
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    data[i][j] = puzzle[i + top][j + left];
                }
            }
        }

        public boolean eq(fullPiece other) {
            return eq0(other) || eq90(other) || eq180(other) || eq270(other);
        }

        private boolean eq0(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[i][j] != other.data[i][j]) return false;
                }
            }
            return true;
        }

        private boolean eq180(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[Y - i - 1][X - j - 1] != other.data[i][j]) return false;
                }
            }
            return true;
        }

        private boolean eq90(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            if (other.data[0].length != Y) return false;
            if (other.data.length != X) return false;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[X - j - 1][i] != other.data[i][j]) return false;
                }
            }
            return true;
        }

        private boolean eq270(fullPiece other) {
            int Y = data.length;
            int X = data[0].length;
            if (other.data[0].length != Y) return false;
            if (other.data.length != X) return false;
            for (int i = 0; i < Y; i++) {
                for (int j = 0; j < X; j++) {
                    if (data[j][Y - i - 1] != other.data[i][j]) return false;
                }
            }
            return true;
        }

    }
}

import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.ArrayDeque;
import java.util.Collections;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        final int INF = 0x3f3f3f3f;
        String[] matrix;
        int[][] zoneIndex;
        int zones;
        int[] dx = new int[]{-1, 0, 1, 0};
        int[] dy = new int[]{0, 1, 0, -1};
        int blackNodes;
        List<Integer>[] graph;

        @SuppressWarnings("unchecked")
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt(), m = in.nextInt();
            matrix = new String[n];
            for (int i = 0; i < n; ++i)
                matrix[i] = in.next();

            zoneIndex = new int[n][m];
            for (int[] p : zoneIndex) Arrays.fill(p, -1);
            zones = 0;
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (matrix[i].charAt(j) == 'B' && zoneIndex[i][j] == -1) {
                        dfs(i, j);
                        zones++;
                    }
                }
            }
            blackNodes = zones;
            if (zones <= 1) {
                out.println(zones);
                return;
            }
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    if (matrix[i].charAt(j) == 'W' && zoneIndex[i][j] == -1) {
                        dfs(i, j);
                        zones++;
                    }
                }
            }

            graph = new List[zones];
            for (int i = 0; i < zones; ++i)
                graph[i] = new ArrayList<>();
            for (int i = 0; i < n; ++i) {
                for (int j = 0; j < m; ++j) {
                    getEdges(i, j);
                }
            }
            for (int i = 0; i < zones; ++i) {
                Collections.sort(graph[i]);
                List<Integer> adj = new ArrayList<>();
                int prev = -1;
                for (int p : graph[i]) {
                    if (p != prev) {
                        adj.add(p);
                        prev = p;
                    }
                }
                graph[i] = adj;
            }

            Queue<Integer> q = new ArrayDeque<>();
            int ans = INF;
            for (int i = 0; i < zones; ++i) {
                int[] dist = new int[zones];
                dist[i] = 1;
                q.add(i);
                int mdist = 1;
                while (!q.isEmpty()) {
                    int node = q.poll();
                    mdist = dist[node];
                    for (int p : graph[node]) {
                        if (dist[p] == 0) {
                            dist[p] = dist[node] + 1;
                            q.add(p);
                        }
                    }
                }
                if (i >= blackNodes) mdist &= ~1;
                else mdist -= (mdist & 1) ^ 1;
                ans = Math.min(ans, mdist);
            }

            out.println(ans);
        }

        private void dfs(int x, int y) {
            zoneIndex[x][y] = zones;
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (0 <= nx && nx < matrix.length &&
                        0 <= ny && ny < matrix[0].length() &&
                        matrix[x].charAt(y) == matrix[nx].charAt(ny) &&
                        zoneIndex[nx][ny] == -1) {
                    dfs(nx, ny);
                }
            }
        }

        private void getEdges(int x, int y) {
            int node = zoneIndex[x][y];
            for (int k = 0; k < 4; ++k) {
                int nx = x + dx[k], ny = y + dy[k];
                if (!(0 <= nx && nx < matrix.length &&
                        0 <= ny && ny < matrix[0].length())) continue;
                int p = zoneIndex[nx][ny];
                if (p != node) {
                    graph[node].add(p);
                }
            }
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new UnknownError();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

import java.io.*;
import java.util.*;

public class Main {

  static class Pair implements Comparable<Pair> {
    public Integer first;
    public Integer second;
    public Pair(Integer first, Integer second) {
      this.first = first;
      this.second = second;
    }
    @Override
    public int compareTo(Pair other) {
      return this.first.compareTo(other.first);
    }
  }

  static class Node {
    public int isBlock = 0;
    public Node[] child;
    public Node pre;
    public Node() {
      this.isBlock = 0;
      this.pre = null;
      this.child = new Node[2];
      Arrays.fill(child, null);
    }
  }

  private static int maxn = 1000001;
  private static int MAX = 2;
  private static String[] ans = new String[10001];
  private static String s;

  private static Node root = new Node();

  private static boolean add(int l) {
    Node temp = root;
    if (root.isBlock == 1)
      return false;
    s = "";
    for (int i = 0; i < l; i++) {
      int check_l = -1;
      boolean canmove = false;
      for (int j = MAX - 1; j >= 0; j--) {
        if (temp.child[j] != null) {
          if (temp.child[j].isBlock == 0) {
            s = s + (char) ('0' + j);
            temp = temp.child[j];
            canmove = true;
            break;
          }
        }
        if (temp.child[j] == null)
          check_l = j;
      }

      if (!canmove) {
        if (check_l == -1)
          return false;
        else {
          s = s + (char) ('0' + check_l);
          temp.child[check_l] = new Node();
          temp.child[check_l].pre = temp;
          temp = temp.child[check_l];
        }
      }
    }

    temp.isBlock = 1;

    while (temp != null) {
      if (temp.child[0] != null && temp.child[1] != null)
        if (temp.child[0].isBlock * temp.child[1].isBlock == 1)
          temp.isBlock = 1;
      temp = temp.pre;
    }

    return true;

  }

  public static void main(String[] args) {

      Scanner sc = new Scanner(System.in);
      int n = sc.nextInt();
      Pair[] a = new Pair[n + 1];
      for (int i = 0; i < n; i++) {
        int l = sc.nextInt();
        a[i] = new Pair(l, i);
      }

      Arrays.sort(a, 0, n);

      for (int i = 0; i < n; i++) {
        int l = a[i].first;
        if (add(l) == false) {
          System.out.println("NO");
          return;
        }
        else
          ans[a[i].second] = s;
      }

      System.out.println("YES");
      for (int i = 0; i < n; i++)
        System.out.println(ans[i]);

      sc.close();

  }

}

