import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.HashSet;
import java.util.Set;
import java.util.StringTokenizer;

public class Rooms implements Runnable {
    static class Door {
        int a;
        int b;
    }

    static class Component {
        Set<String> names = new HashSet<String>();
        Set<Door> keys = new HashSet<Door>();

        public int size() {
            return names.size() + keys.size();
        }
    }

    private void solve() throws IOException {
        int n = nextInt();
        int m = nextInt();
        int k = nextInt();
        Door[] door = new Door[m];
        for (int i = 0; i < m; ++i) {
            door[i] = new Door();
            door[i].a = nextInt() - 1;
            door[i].b = nextInt() - 1;
        }
        Component[][] res = new Component[2][];
        for (int step = 0; step < 2; ++step) {
            Component[] where = new Component[n];
            for (int i = 0; i < n; ++i) {
                where[i] = new Component();
            }
            for (int i = 0; i < k; ++i) {
                String name = nextToken();
                int room = nextInt() - 1;
                Component cur = where[room];
                cur.names.add(name);
                int cnt = nextInt();
                for (int j = 0; j < cnt; ++j) {
                    cur.keys.add(door[nextInt() - 1]);
                }
            }
            while (true) {
                boolean changed = false;
                for (Door d : door) {
                    if (where[d.a] == where[d.b])
                        continue;
                    if (where[d.a].keys.contains(d) || where[d.b].keys.contains(d)) {
                        changed = true;
                        Component a = where[d.a];
                        Component b = where[d.b];
                        a.keys.addAll(b.keys);
                        a.names.addAll(b.names);
                        for (int i = 0; i < n; ++i)
                            if (where[i] == b)
                                where[i] = a;
                    }
                }
                if (!changed)
                    break;
            }
            res[step] = where;
        }
        boolean result = true;
        for (int i = 0; i < n; ++i) {
            Component a = res[0][i];
            Component b = res[1][i];
            if (a.names.equals(b.names) && a.keys.equals(b.keys))
                continue;
            result = false;
            break;
        }
        if (result)
            writer.println("YES");
        else
            writer.println("NO");

    }

    public static void main(String[] args) {
        new Rooms().run();
    }

    BufferedReader reader;
    StringTokenizer tokenizer;
    PrintWriter writer;

    public void run() {
        try {
            reader = new BufferedReader(new InputStreamReader(System.in));
            tokenizer = null;
            writer = new PrintWriter(System.out);
            solve();
            reader.close();
            writer.close();
        } catch (Exception e) {
            e.printStackTrace();
            System.exit(1);
        }
    }

    int nextInt() throws IOException {
        return Integer.parseInt(nextToken());
    }

    long nextLong() throws IOException {
        return Long.parseLong(nextToken());
    }

    double nextDouble() throws IOException {
        return Double.parseDouble(nextToken());
    }

    String nextToken() throws IOException {
        while (tokenizer == null || !tokenizer.hasMoreTokens()) {
            tokenizer = new StringTokenizer(reader.readLine());
        }
        return tokenizer.nextToken();
    }
}

import java.util.Scanner;

public class CF67E {
	static int[] x, y;

	static long cross(int i, int j, int k) {
		long x1=x[j] - x[i];
		long x2=x[k] - x[i];
		long y1=y[j] - y[i];
		long y2=y[k] - y[i];
		return x1 * y2 - x2 * y1;
	}


	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int n = sc.nextInt();
		x = new int[n];
		y = new int[n];
		for (int i = 0; i < n; i++) {
			x[i] = sc.nextInt();
			y[i] = sc.nextInt();
		}

		boolean flip = x[0] < x[1];
		int X = x[1], Y = y[1];
		for (int i = 0; i < n; i++) {
			x[i] -= X;
			y[i] -= Y;
			if (flip) {
				x[i] = -x[i];
				y[i] = -y[i];
			}
		}

		int l = 0, r = x[0];
		for (int i = 2; i + 1 < n; i++) {
			long cr = cross(i, i + 1, 0);
			long cl = cross(i, i + 1, 1);
			if (cr > 0 && cl > 0) {
				System.out.println(0);
				return;
			}
			int x0 = x[i], y0 = y[i], x1 = x[i + 1], y1 = y[i + 1];
			if (cr > 0 || cl > 0) {
				long p = (long) x0 * (y1 - y0) - (long) y0 * (x1 - x0);
				long q = y1 - y0;
				if (q < 0) {
					p = -p; q = -q;
				}
				if (cr > 0)
					r = Math.min(r, (int) (p / q));
				else
					l = Math.max(l, (int) ((p + q - 1) / q));
			}
		}
		System.out.println(l <= r ? r - l + 1 : 0);

	}	
}

