                y.T[0] = 1;
                y.T[1] = 0;
                return y;
            }
        int z;
        z = x;
        y.T[0] = 0;
        while (z!=0)
            {
                y.T[0]++;
                y.T[y.T[0]] = z % 10;
                z = z / 10;
            }

        return y;
    }

entier somme(entier x,entier y)
    {
        if ((x.T[0]==1) && (x.T[1]==0)) return y;
        if ((y.T[0]==1) && (y.T[1]==0)) return x;
        int i,retenu;
        entier z;
        z.T[0] = 0;
        i = 1;
        retenu = 0;
        while ((i<=x.T[0]) || (i<=y.T[0]) || (retenu!=0))
            {
                z.T[0]++;
                if (i<=x.T[0]) retenu = retenu + x.T[i];
                if (i<=y.T[0]) retenu = retenu + y.T[i];
                z.T[z.T[0]] = retenu % 10;
                retenu = retenu / 10;
                i++;
            }
        return z;
    }

entier difference(entier x,entier y)
    {
        if ((y.T[0]==1) && (y.T[1]==0)) return x;
        int i,retenu;
        entier z;
        z.T[0] = 0;
        retenu = 0;
        for (i=1;i<=x.T[0];i++)
            {
                z.T[0]++;
                if (i<=y.T[0]) retenu = retenu + y.T[i];
                if (x.T[i]<retenu)
                    {
                        z.T[z.T[0]] = x.T[i] + 10 - retenu;
                        retenu = 1;
                    }
                else
                    {
                        z.T[z.T[0]] = x.T[i] - retenu;
                        retenu = 0;
                    }
            }
        i = z.T[0];
        while ((0<i) && (z.T[i]==0))
            {
                z.T[0]--;
                i--;
            }
        if (i==0) z.T[0] = 1;
        return z;
    }

entier multiplierChiffre(int x,entier y)
    {
        if ((y.T[0]==1) && (y.T[1]==0)) return y;
        entier z;
        if (x==0)
            {
                z.T[0] = 1;
                z.T[1] = 0;
                return z;
            }
        int i,retenu;
        i = 1;
        retenu = 0;
        z.T[0] = 0;
        while ((i<=y.T[0]) || (retenu!=0))
            {
                z.T[0]++;
                if (i<=y.T[0]) retenu = retenu + (x * y.T[i]);
                z.T[z.T[0]] = retenu % 10;
                retenu = retenu / 10;
                i++;
            }
        return z;
    }

entier decalage(int x,entier y)
    {
        if ((y.T[0]==1) && (y.T[1]==0)) return y;
        if (x==0) return y;
        int i;
        entier z;
        z.T[0] = y.T[0] + x;
        for (i=y.T[0];i>0;i--) z.T[i+x] = y.T[i];
        for (i=1;i<=x;i++) z.T[i] = 0;
        return z;
    }

entier produit(entier x,entier y)
    {
        if ((x.T[0]==1) && (x.T[1]==0)) return x;
        if ((y.T[0]==1) && (y.T[1]==0)) return y;
        int i;
        entier z;
        z = transformer(0);
        for (i=1;i<=y.T[0];i++) z = somme(z,decalage(i-1,multiplierChiffre(y.T[i],x)));
        return z;
    }

int comparer(entier x,entier y)
    {
        if (x.T[0]<y.T[0]) return (-1);
        if (y.T[0]<x.T[0]) return 1;
        int i;
        i = x.T[0];
        while ((0<i) && (x.T[i]==y.T[i])) i--;
        if (i==0) return 0;
        if (x.T[i]<y.T[i]) return (-1);
        return 1;
    }

