	qsort(a, n, sizeof(int), comp);
	for(i=n-1;i>0;--i){
		for(j=0;j<=n;++j){
			add=j*(a[i]-a[i-1]);
			for(l=0;l<=k;++l){
				dp[i&1][j][l]=(get(i+1, j+1, l+add)+j*get(i+1, j-1, l+add)+
						(j+1)*get(i+1, j, l+add))%mod;
			}
		}
	}
	printf("%I64d\n", (get(1, 1, 0)+get(1, 0, 0))%mod);
