double abso(double a)
{
    return (a<0)?-a:a;
}




char verify(int index,int i,int j)
{
    double edge[2];
    double point[2];
    sub(edge,A[j],A[i]);
    sub(point,B[index],A[i]);
    if (cross(point,edge)>EPS)
        return 1;
    else
        return 0;
}



char binary_search(int index)
{
    double b[2];
    double m_b[2];
    double m[2];
    double m_a[2];
    sub(b,B[index],A[0]);
    int mid;
    int lo=1,hi=N-1;
    while(lo<=hi)
    {
        mid=lo + (hi-lo)/2;
        sub(m,A[mid],A[0]);
        if (mid>0)
        {
            sub(m_b,A[mid-1],A[0]);
            if(abso(cross(b,m))<EPS || abso(cross(b,m_b))<EPS || (cross(b,m)*cross(b,m_b))<0)
            {
                if (!verify(index,mid-1,mid))
                    return 0;
                else
                    return 1;
            }
        }
        if (mid<N-1)
        {
            sub(m_a,A[mid+1],A[0]);
            if(abso(cross(b,m))<EPS || abso(cross(b,m_a))<EPS || (cross(b,m)*cross(b,m_a))<0)
            {
                if (!verify(index,mid,mid+1))
                    return 0;
                else
                    return 1;
            }
        }
        if (cross(b,m)<0)
            hi=mid-1;
        else
            lo=mid+1;
    } 
    /*error*/
    return -1;
}


