void trim(char *s) {
	static char t[128];
	int n, m, i;

	memset(t, 0, sizeof t);
	n = strlen(s);
	for (i = 0, m = 0; i < n; i++)
		if (!isspace(s[i]))
			t[m++] = s[i];
	strcpy(s, t);
}

int isop(char c) {
	return c == '[' || c == ']' || c == '(' || c == ')' || c == '+' || c == '-' || c == '*' || c == '/';
}

int xx[M], yy[M];

int replace(char *ss, char *s, char *t, int x) {
	static char s_[M + 1];
	int n, m, l, n_, i, change;

	n = strlen(ss);
	m = strlen(s);
	l = strlen(t);
	memset(s_, 0, sizeof s_);
	n_ = 0;
	change = 0;
	memset(xx, 0, sizeof xx);
	for (i = 0; i < n; )
		if (i + m <= n && strncmp(ss + i, s, m) == 0 && (i == 0 || isop(ss[i - 1])) && (i + m == n || isop(ss[i + m]))) {
			xx[n_] = x;
			s_[n_++] = '[';
			memcpy(s_ + n_, t, l);
			n_ += l;
			s_[n_++] = ']';
			i += m;
			change = 1;
		} else {
			xx[n_] = yy[i];
			s_[n_++] = ss[i++];
		}
	strcpy(ss, s_);
	memset(yy, 0, sizeof yy);
	memcpy(yy, xx, n_ * sizeof *xx);
	return change;
}

static char t1[N][128], t2[N][128];
static char aa[N + 1], bb[N + 1], cc[N + 1];
int n;

void parse(char *ss, int x) {
	static int stack[M];
	int m, i, j, j_, x_, cnt, cnt_;

	aa[x] = 1;
	memset(yy, 0, sizeof yy);
	for (i = 0; i < x; i++)
		if (replace(ss, t1[i], t2[i], i) && !aa[i]) {
			aa[x] = bb[x] = cc[x] = 0;
			return;
		}
	bb[x] = cc[x] = 0;
	m = strlen(ss);
	for (j = 0, cnt = 0, cnt_ = 0; j < m; j++) {
		if (ss[j] == '[')
			stack[cnt++] = j;
		else if (ss[j] == ']') {
			j_ = stack[--cnt], x_ = xx[j_];
			if (j_ > 0) {
				if ((ss[j_ - 1] == '*' || ss[j_ - 1] == '/') && bb[x_]) {
					aa[x] = bb[x] = cc[x] = 0;
					return;
				}
				if (ss[j_ - 1] == '-' && bb[x_]) {
					aa[x] = bb[x] = cc[x] = 0;
					return;
				}
				if (ss[j_ - 1] == '/' && cc[x_]) {
					aa[x] = bb[x] = cc[x] = 0;
					return;
				}
			}
			if (j + 1 < m && (ss[j + 1] == '*' || ss[j + 1] == '/') && bb[x_]) {
				aa[x] = bb[x] = cc[x] = 0;
				return;
			}
			if (bb[x_] && cnt_ == 0)
				bb[x] = 1;
			if (cc[x_] && cnt_ == 0)
				cc[x] = 1;
		}
		if ((ss[j] == '+' || ss[j] == '-') && cnt_ == 0)
			bb[x] = 1;
		else if ((ss[j] == '*' || ss[j] == '/') && cnt_ == 0)
			cc[x] = 1;
		if (ss[j] == '(')
			cnt_++;
		else if (ss[j] == ')')
			cnt_--;
	}
}

int main() {
	static char ss[M + 2], tt[M + 2], s[128];
	int i, len;

	scanf("%d", &n);
	for (i = 0; i < n; i++) {
		len = 0;
		while (len < 7) {
			scanf("%s", s);
			len += strlen(s);
		}
		scanf("%s", t1[i]);
		fgets(t2[i], 128, stdin);
		trim(t2[i]);
	}
	fgets(ss, M + 2, stdin);
	trim(ss);
	for (i = 0; i <= n; i++) {
		strcpy(tt, i < n ? t2[i] : ss);
		parse(tt, i);
	}
	printf(aa[n] ? "OK\n" : "Suspicious\n");
	return 0;
}

