/* count cycles going through first, with no nodes >first */
ll solve(int first,int at,int mask) {
  ll res=0;
  int i;
  if(dp[at][mask]>-1) return dp[at][mask];
  /* can go back? only if cycle is of length >=3 */
  if(g[first][at] && bc[mask]>=2) res++;
  for(i=0;i<first;i++) if(g[at][i] && !(mask&(1<<i))) {
    res+=solve(first,i,mask|(1<<i));
  }
/*  printf("cycle at %d %d, mask ",first,at);
  printmask(mask);
  printf(": %I64d\n",res);*/
  return dp[at][mask]=res;
}

