int par[100];

int find(int x)
{
     if (par[x] == x) {
	  return x;
     } else {
	  return par[x] = find(par[x]);
     }
}

void unite(int x, int y)
{
     x = find(x);
     y = find(y);

     if (x == y) return;

     par[x] = y;
}

int same(int x, int y)
{
     x = find(x);
     y = find(y);

     if (x == y) {
	  return 1;
     } else {
	  return 0;
     }
}

