long getf(long now)
{
   if (f[now]==now)
      return now;
   return f[now]=getf(f[now]);
}

void dfs(long now,long x)
{
   long i,j,fa,tmp;
   hash[x][now]=1;
   stay[now][++ps[now]]=x;
   tmp=++flag;
   for (i=1;i<ps[now];i++)
      if (x!=(fa=getf(stay[now][i])))
      {
         f[fa]=x;
         for (j=1;j<=m;j++)
            if (own[fa][j]&&!own[x][j])
            {
               own[x][j]=1;
               rec[j]=flag;
            }
         for (j=1;j<=n;j++)
            hash[x][j]|=hash[fa][j];
      }
   for (i=1;i<=m;i++)
      if (rec[i]==tmp)
         if (hash[x][ed[i][0]]&&!hash[x][ed[i][1]])
            dfs(ed[i][1],x);
         else if (hash[x][ed[i][1]]&&!hash[x][ed[i][0]])
            dfs(ed[i][0],x);
   for (i=head[now];i;i=next[i])
      if (!hash[x][e[i]]&&own[x][v[i]])
         dfs(e[i],x);
}

