int n,m;
char input[11][36] = {{'\0'},{'\0'}};
int errors[11] = {0};
int poss = 0;
char arr[36] = {0};
int visited[11] = {0};
int check()
{
    int counter =0;
    for (int i=0;i<m;i++)
    {
        int counter=0;
        for (int j =0;j<n;j++)
        {
            if (input[i][j] != arr[j])
                counter++;
        }
        if (counter != errors[i])
            return 0;
    }
    return 1;
}
char change(char num)
{
    if (num == '0')
        return '1';
    else
        return '0';
}

void solve (int place,int var)
{
    if (var == 0)
    {
        if (check())
            poss++;
            return;
    }
    if (place == n)
        return;
    arr[place] =change(arr[place]);
    solve(place+1,var-1);
    arr[place] = change(arr[place]);
    solve (place+1,var);
}

