#define N	1000

int min(int a, int b) { return a < b ? a : b; }
int max(int a, int b) { return a > b ? a : b; }

int xx[N], yy[N];

long long cross2(long long x1, long long y1, long long x2, long long y2) {
	return x1 * y2 - x2 * y1;
}

long long cross(int i, int j, int k) {
	return cross2(xx[j] - xx[i], yy[j] - yy[i], xx[k] - xx[i], yy[k] - yy[i]);
}

int main() {
	int n, i, flip, x, y, l, r;

	scanf("%d", &n);
	for (i = 0; i < n; i++)
		scanf("%d%d", &xx[i], &yy[i]);
	flip = xx[0] < xx[1];
	x = xx[1], y = yy[1];
	for (i = 0; i < n; i++) {
		xx[i] -= x;
		yy[i] -= y;
		if (flip) {
			xx[i] = -xx[i];
			yy[i] = -yy[i];
		}
	}
	l = 0, r = xx[0];
	for (i = 2; i + 1 < n; i++) {
		long long cr = cross(i, i + 1, 0);
		long long cl = cross(i, i + 1, 1);
		int x0, y0, x1, y1;

		if (cr > 0 && cl > 0) {
			printf("0\n");
			return 0;
		}
		x0 = xx[i], y0 = yy[i], x1 = xx[i + 1], y1 = yy[i + 1];
		if (cr > 0 || cl > 0) {
			long long p = (long long) x0 * (y1 - y0) - (long long) y0 * (x1 - x0);
			long long q = y1 - y0;

			if (q < 0)
				p = -p, q = -q;
			if (cr > 0)
				r = min(r, p / q);
			else
				l = max(l, (p + q - 1) / q);
		}
	}
	printf("%d\n", l <= r ? r - l + 1 : 0);
	return 0;
}

#include <stdio.h>
#include <stdlib.h>

#define X	1000000
#define Q	100000

long long cross2(long long x1, long long y1, long long x2, long long y2) {
	return x1 * y2 - x2 * y1;
}

struct P {
	int x, y;
} *pl, *pr;

typedef struct P *T[(X + X + 1) * 4];

long long cross(struct P *o, struct P *p, struct P *q) {
	return cross2(p->x - o->x, p->y - o->y, q->x - o->x, q->y - o->y);
}

struct P *min(struct P *p, struct P *q) {
	return p != NULL && q != NULL ? (p->x < q->x ? p : q) : (p == NULL ? q : p);
}

struct P *max(struct P *p, struct P *q) {
	return p != NULL && q != NULL ? (p->x > q->x ? p : q) : (p == NULL ? q : p);
}

void update(T tl, T tr, int k, int l, int r, int x, struct P *p) {
	int m;

	if (r - l == 1) {
		tl[k] = tr[k] = p;
		return;
	}
	m = (l + r) / 2;
	if (x < m)
		update(tl, tr, k * 2 + 1, l, m, x, p);
	else
		update(tl, tr, k * 2 + 2, m, r, x, p);
	tr[k] = min(tr[k * 2 + 1], tr[k * 2 + 2]);
	tl[k] = max(tl[k * 2 + 1], tl[k * 2 + 2]);
}

void query(T tl, T tr, int k, int l, int r, int x) {
	int m;

	if (r - l == 1) {
		pl = max(pl, tl[k]);
		pr = min(pr, tr[k]);
		return;
	}
	m = (l + r) / 2;
	if (x < m) {
		pr = min(pr, tr[k * 2 + 2]);
		query(tl, tr, k * 2 + 1, l, m, x);
	} else {
		pl = max(pl, tl[k * 2 + 1]);
		query(tl, tr, k * 2 + 2, m, r, x);
	}
}

int query_(T tl_up, T tr_up, T tl_dn, T tr_dn, struct P *p, int insert) {
	struct P *q, *pl_, *pr_;
	int inside = 1;

	pl = pr = NULL;
	query(tl_up, tr_up, 0, 0, X + X + 1, p->x);
	pl_ = pl, pr_ = pr;
	if ((pl == pr
				&& (pl == NULL || pl->y < p->y))
			|| (pl != pr
				&& (pl == NULL || pr == NULL || cross(pl, p, pr) < 0))) {
		if (insert) {
			for (q = pl_; q && q->x > 0; q = pl) {
				pl = pr = NULL;
				query(tl_up, tr_up, 0, 0, X + X + 1, q->x - 1);
				if (!pl || cross(pl, q, p) < 0)
					break;
				update(tl_up, tr_up, 0, 0, X + X + 1, q->x, NULL);
			}
			for (q = pr_; q && q->x < X + X; q = pr) {
				pl = pr = NULL;
				query(tl_up, tr_up, 0, 0, X + X + 1, q->x + 1);
				if (!pr || cross(p, q, pr) < 0)
					break;
				update(tl_up, tr_up, 0, 0, X + X + 1, q->x, NULL);
			}
			update(tl_up, tr_up, 0, 0, X + X + 1, p->x, p);
		}
		inside = 0;
	}
	pl = pr = NULL;
	query(tl_dn, tr_dn, 0, 0, X + X + 1, p->x);
	pl_ = pl, pr_ = pr;
	if ((pl == pr
				&& (pl == NULL || pl->y > p->y))
			|| (pl != pr
				&& (pl == NULL || pr == NULL || cross(pl, p, pr) > 0))) {
		if (insert) {
			for (q = pl_; q && q->x > 0; q = pl) {
				pl = pr = NULL;
				query(tl_dn, tr_dn, 0, 0, X + X + 1, q->x - 1);
				if (!pl || cross(pl, q, p) > 0)
					break;
				update(tl_dn, tr_dn, 0, 0, X + X + 1, q->x, NULL);
			}
			for (q = pr_; q && q->x < X + X; q = pr) {
				pl = pr = NULL;
				query(tl_dn, tr_dn, 0, 0, X + X + 1, q->x + 1);
				if (!pr || cross(p, q, pr) > 0)
					break;
				update(tl_dn, tr_dn, 0, 0, X + X + 1, q->x, NULL);
			}
			update(tl_dn, tr_dn, 0, 0, X + X + 1, p->x, p);
		}
		inside = 0;
	}
	return inside;
}

int main() {
	static T tl_up, tr_up, tl_dn, tr_dn;
	int q;

	scanf("%d", &q);
	while (q-- > 0) {
		struct P *p = malloc(sizeof *p);
		int t;

		scanf("%d%d%d", &t, &p->x, &p->y);
		p->x += X;
		if (t == 1)
			query_(tl_up, tr_up, tl_dn, tr_dn, p, 1);
		else
			printf(query_(tl_up, tr_up, tl_dn, tr_dn, p, 0) ? "YES\n" : "NO\n");
	}
	return 0;
}

