      if (n == 24)
      {
        if(s[0] > 23)
          s[0] %= 10;
      }
      else
      {
        if (s[0] == 0)
          s[0] = 1;
        else if(s[0] > 12)
        {
          if (s[0] % 10 == 0)
            s[0] = 10;
          else
            s[0] %= 10;
        }
      }
      if (s[1] > 59)
      {
        s[1] %= 10;
      }
      Console.Write($"{s[0].ToString("00")}:{s[1].ToString("00")}");
    }

