namespace Picking_Strings
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);

        private static void Main(string[] args)
        {
            Solve(args);
            writer.Flush();
        }

        private static void Solve(string[] args)
        {
            string s = reader.ReadLine();
            string t = reader.ReadLine();

            var ss = new int[s.Length + 1];
            var sa = new int[s.Length + 1];
            for (int i = 0; i < s.Length; i++)
            {
                if (s[i] == 'A')
                {
                    ss[i + 1] = ss[i];
                    sa[i + 1] = sa[i] + 1;
                }
                else
                {
                    ss[i + 1] = ss[i] + 1;
                }
            }
            var tt = new int[t.Length + 1];
            var ta = new int[t.Length + 1];
            for (int i = 0; i < t.Length; i++)
            {
                if (t[i] == 'A')
                {
                    tt[i + 1] = tt[i];
                    ta[i + 1] = ta[i] + 1;
                }
                else
                {
                    tt[i + 1] = tt[i] + 1;
                }
            }

            int Q = Next();

            while (Q-- > 0)
            {
                int a = Next(), b = Next(), c = Next(), d = Next();
                int cs = ss[b] - ss[a - 1];
                int ct = tt[d] - tt[c - 1];

                int esa = Math.Min(sa[b], b - a + 1);
                int eta = Math.Min(ta[d], d - c + 1);

                writer.Write(
                    cs > ct ||
                    cs < ct && (ct - cs)%2 != 0 ||
                    cs == ct && (eta > esa || eta < esa && (esa - eta)%3 != 0) ||
                    eta > 0 && (eta > esa || eta == esa && cs == 0 && ct > 0 || eta < esa && cs >= ct && (esa - eta)%3 != 0)
                        ? '0'
                        : '1');
            }
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == 'A')
                    return 0;
                if (c == 'B' || c == 'C')
                    return 1;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

