    internal class Solution
    {
        public void Solve()
        {
            long a, b, k;
            Reader.ReadLong(out a, out b, out k);

            long lcm = 1;
            for (int i = 1; i < k + 1; i++)
            {
                lcm = Algebra.Lcm(lcm, i);
            }

            int[] v = new int[k * lcm];

            Queue<int> queue = new Queue<int>();

            v[a % lcm] = 0;

            var d1 = this.Run((int)(a % lcm), (int)lcm, (int)k);
            var d2 = this.Run((int)(lcm - 1), (int)lcm, (int)k);

            long l1 = a / lcm;
            long l2 = b / lcm;
            if (l1 == l2)
            {
                Console.WriteLine(d1[b % lcm]);
            }
            else
            {
                Console.WriteLine(d1[0] + (l1 - l2 - 1) * (d2[0] + 1) + 1 + d2[b % lcm]);
            }
        }

        int[] Run(int start, int lcm, int k)
        {
            var result = new int[lcm];
            for (int i = 0; i < lcm; i++)
            {
                result[i] = lcm + 1;
            }

            var queue = new Queue<int>();
            queue.Enqueue(start);
            result[start] = 0;

            while (queue.Count > 0)
            {
                int current = queue.Dequeue();
                int dist = result[current];
                for (int i = 2; i <= k; i++)
                {
                    int next = current - current % i;
                    if (result[next] > dist + 1)
                    {
                        result[next] = dist + 1;
                        queue.Enqueue(next);
                    }
                }
                if (current > 0 && result[current - 1] > dist + 1)
                {
                    result[current - 1] = dist + 1;
                    queue.Enqueue(current - 1);
                }
            }

            return result;
        }
    }
