public class Solver
{
    int[] KMP(string s)
    {
        int n = s.Length;
        var pi = new int[n];
	    for (int i = 1; i < n; ++i) 
        {
		    int j = pi[i - 1];
		    while (j > 0 && s[i] != s[j])
			    j = pi[j - 1];
		    if (s[i] == s[j])
                j++;
		    pi[i] = j;
	    }
	    return pi;
    }

    public object Solve()
    {
        string s1 = ReadToken();
        string s2 = ReadToken();
        string s3 = ReadToken();

        int n1 = s1.Length;
        int n2 = s2.Length;
        int n3 = s3.Length;

        var dp = new int[n1 + 1, n2 + 1, n3];
        var path = new Tuple<int, int, int, char>[n1 + 1, n2 + 1, n3];
        for (int i1 = 1; i1 <= n1; i1++)
            for (int i2 = 1; i2 <= n2; i2++)
                for (int i3 = 0; i3 < n3; i3++)
                {
                    if (s1[i1 - 1] == s2[i2 - 1])
                    {
                        if (s3[i3] == s1[i1 - 1])
                        {
                            if (i3 + 1 < n3)
                            {
                                dp[i1, i2, i3 + 1] = dp[i1 - 1, i2 - 1, i3] + 1;
                                path[i1, i2, i3 + 1] = Tuple.Create(i1 - 1, i2 - 1, i3, s1[i1 - 1]);
                            }
                        }
                        else
                        {
                            int jump = KMP(s3.Substring(0, i3) + s1[i1 - 1])[i3];
                            if (dp[i1 - 1, i2 - 1, i3] + 1 > dp[i1, i2, jump])
                            {
                                dp[i1, i2, jump] = dp[i1 - 1, i2 - 1, i3] + 1;
                                path[i1, i2, jump] = Tuple.Create(i1 - 1, i2 - 1, i3, s1[i1 - 1]);
                            }
                        }
                    }
                    if (dp[i1 - 1, i2, i3] >= dp[i1, i2, i3])
                    {
                        dp[i1, i2, i3] = dp[i1 - 1, i2, i3];
                        path[i1, i2, i3] = Tuple.Create(i1 - 1, i2, i3, (char)0);
                    }
                    if (dp[i1, i2 - 1, i3] >= dp[i1, i2, i3])
                    {
