                        path[i1, i2, i3] = Tuple.Create(i1, i2 - 1, i3, (char)0);
                    }
                }

        int max = -1;
        int nmax = -1;
        for (int i = 0; i < n3; i++)
        {
            if (dp[n1, n2, i] > max)
            {
                max = dp[n1, n2, i];
                nmax = i;
            }
        }
        if (max == 0)
            return 0;

        var list = new List<char>();
        var c = Tuple.Create(n1, n2, nmax, (char)0);
        while (c.Item1 > 0 && c.Item2 > 0)
        {
            c = path[c.Item1, c.Item2, c.Item3];
            if (c.Item4 > 0)
                list.Add(c.Item4);
        }
        list.Reverse();

//        for (int i = 0; i < n3; i++)
