namespace ProgrammingContest.Codeforces.Round77
{
    class B
    {
        static string s;
        static char[] cs;
        static char[] val = new char[2] { '4', '7' };
        static bool dfs2(int i, int c4, int c7, bool eq)
        {
            if (i >= s.Length)
                return c4 == c7;
            for (int j = 0; j < 2; j++)
            {
                if (eq && val[j] < s[i])
                    continue;
                cs[i] = val[j];
                if (dfs2(i + 1, c4 + 1 - j, c7 + j, eq && s[j] == cs[i]))
                    return true;
            }
            return false;
        }
        static bool dfs()
        {
            Stack<char> sc = new Stack<char>();
            Stack<int> si = new Stack<int>();
            Stack<int> s4 = new Stack<int>();
            Stack<int> s7 = new Stack<int>();
            Stack<bool> seq = new Stack<bool>();

            si.Push(0);
            s4.Push(0);
            s7.Push(0);
            seq.Push(true);

            while (si.Any())
            {
                int i = si.Pop(),
                    c4 = s4.Pop(),
                    c7 = s7.Pop();
                if (i > 0) cs[i - 1] = sc.Pop();
                bool eq = seq.Pop();
                if (Math.Min(c4, c7) + s.Length - i < Math.Max(c4, c7))
                    continue;
                if (i >= s.Length)
                {
                    if (c4 == c7)
                        return true;
                    continue;
                }
                for (int j = 1; j >= 0; j--)
                {
                    if (eq && val[j] < s[i])
                        continue;
                    sc.Push(val[j]);
                    si.Push(i + 1);
                    s4.Push(c4 + 1 - j);
                    s7.Push(c7 + j);
                    seq.Push(eq && s[i] == val[j]);
                }
            }
            return false;
        }

        public static void Main()
        {
            s = Console.ReadLine();
            cs = s.ToCharArray();
            if (s.Length%2 == 0 && dfs())
                Console.WriteLine(new string(cs));
            else
            {
                int len = s.Length;
                if (len % 2 == 0) len = len / 2 + 1;
                else if (len % 2 == 1) len = (len + 1) / 2;
                for (int i = 0; i < len * 2; i++)
                    Console.Write(i < len ? '4' : '7');
                Console.WriteLine();
            }
            return;
            for (int t = 7700; t <= 7900; t++)
            {
                //s = '1' + "".PadLeft(99999, '0');
                Console.Write(t + ":");
                s = t.ToString();
                cs = s.ToCharArray();
                if (dfs())
                    Console.WriteLine(new string(cs));
                else
                {
                    int len = s.Length;
                    if (len % 2 == 0) len = len / 2 + 2;
                    if (len % 2 == 1) len = (len + 1) / 2;
                    for (int i = 0; i < len * 2; i++)
                        Console.Write(i < len ? '4' : '7');
                    Console.WriteLine();
                }
            }
        }
    }
