            bool aabb = Rifm(lines[0], lines[1], k) && Rifm(lines[2], lines[3], k);
            bool abab = Rifm(lines[0], lines[2], k) && Rifm(lines[1], lines[3], k);
            bool abba = Rifm(lines[0], lines[3], k) && Rifm(lines[1], lines[2], k);
            if (aabb && abab && abba)
                return 0;
            if (aabb)
                return 1;
            if (abab)
                return 2;
            if (abba)
                return 3;
            return -1;
        }


        static bool Rifm(string a, string b, int k)
        {
            string s1 = Substr(a, k);
            string s2 = Substr(b, k);
            return s1 != null && s2 != null && s1 == s2;
        }

        static string Substr(string a, int k)
        {
            int r = a.Length;
            for (int i = 0; i < k; i++)
            {
//                if (r == a.Length)
//                    r = a.LastIndexOfAny(new char[] { 'a', 'e', 'i', 'o', 'u' });
//                else
                if (r == 0)
                    return null;
                    r = a.LastIndexOfAny(new char[] {'a', 'e', 'i', 'o', 'u'}, r - 1);
                if (r == -1)
                    return null;
            }
            return a.Substring(r);
        }
    }
}

