class Program
{
    long[] a;
    long[,] dp;
    int maxn = 100000;
    void solve()
    {
        //test();
        long n = nextLong();
        a = new long[nextInt()];
        for (int i = 0; i < a.Length; i++)
            a[i] = nextLong();
        long res = n - doIt(n);
        println(res);


    }
    long doIt(long n)
    {
        Array.Sort(a);
        Array.Reverse(a);
        dp = new long[100, maxn];
        for (int i = 0; i < 100; i++)
            for (int j = 0; j < maxn; j++)
                dp[i, j] = -1;
        return go(n, 0);
    }
    private void test()
    {
        long n = 10000000000000;
        int k = 100;
        a = new long[k];
        int cur = 2;
        for (int i = 0; i < k; i++)
        {
            while (!prime(cur))
                cur++;
            a[i] = cur++;
        }
        println(doIt(n));
    }

    private bool prime(int p)
    {
        for (int i = 2; i * i <= p; i++)
            if (p % i == 0)
                return false;
        return true;
    }

    private long go(long n, int at)
    {
        if (at == a.Length)
            return 0;
        if (n == 0)
            return 0;
        if (n < maxn)
        {
            if (dp[at, n] != -1)
                return dp[at, n];
        }
        long res = go(n, at + 1);
        res += n / a[at];
        res -= go(n / a[at], at + 1);
        if (n < maxn)
        {
            return dp[at, n] = res;
        }
        return res;
    }

