    Int32 Have(Int32 dig, Int32 delta, Int32[] stat) {
        Int32 have = 0;
        if (dig - delta >= 0) {
            have += stat[dig - delta];
        }
        if (dig + delta < 10) {
            have += stat[dig + delta];
        }
        return have;
    }

    Int32 Pick(String str, Int32 dig, Int32[] stat, Int32 toChange) {
        Int32[] accDist = new Int32[10];
        toChange -= stat[dig];
        for (Int32 pick, dist = 1; toChange > 0; ++dist) {
            if (dig - dist >= 0) {
                pick = Math.Min(toChange, stat[dig - dist]);
                accDist[dist] += pick;
                toChange -= pick;
            }
            if (dig + dist < 10) {
                pick = Math.Min(toChange, stat[dig + dist]);
                accDist[dist] += pick;
                toChange -= pick;
            }
        }

        Int32 score = 0;
        for (Int32 delta, cur, i = 0; i < str.Length; ++i) {
            cur = str[i] & 0xf;
            delta = Math.Abs(cur - dig);
            if (accDist[delta] != 0) {
                if (cur > dig || accDist[delta] == Have(dig, delta, stat)) {
                    score += delta;
                    --accDist[delta];
                    --stat[cur];
                    cur = dig;
                } else {
                    --stat[cur];
                }
            }
            last[i] = (Char) (cur | 0x30);
        }

        return score;
    }

