    class B {
        static void Main() {
            Scanner sc = Scanner.FromConsole();
            PrintWriter writer = PrintWriter.ToConsole();

            int n = sc.NextInt(),
                k = sc.NextInt();
            var a = sc.NextInts(n);
            var used = new bool[n];
            int q = sc.NextInt();
            var prevs = new List<int>();
            int uniq = 0;
            for (int i = 0; i < q; i++) {
                var xs = sc.NextInts(n/k);
                prevs.Add(0);
                bool already = false;
                for (int j = 0; j < xs.Length; j++) {
                    already = used[xs[j]-1];
                    used[xs[j] - 1] = true;
                    prevs[i] += a[xs[j]-1];
                }
                if(!already) {
                    uniq++;
                }
            }

            List<int> ys = new List<int>();
            for (int i = 0; i < n; i++)
                if (!used[i])
                    ys.Add(a[i]);
            if (uniq < k) {
                ys.Sort();
                int u=0,v=0;
                for (int i = 0; i < n / k; i++) { u += ys[i]; v += ys[ys.Count - 1 - i]; }
                prevs.Add(u);
                prevs.Add(v);
            }
            prevs.Sort();
            double d = n / k;
            writer.WriteLine("{0:F10} {1:F10}", prevs.First() / d, prevs.Last() / d);
        }


        #region PrintWriter
        class PrintWriter : IDisposable {
            System.IO.TextWriter writer;

            public static PrintWriter ToConsole() {
                return new PrintWriter(Console.Out);
            }

            public static PrintWriter ToFile(string path) {
                return new PrintWriter(new System.IO.StreamWriter(path));
            }

            public void Write(string format, params object[] obj) {
                writer.Write(String.Format(System.Globalization.CultureInfo.InvariantCulture, format, obj));
            }

            public void WriteLine(string format, params object[] obj) {
                writer.WriteLine(String.Format(System.Globalization.CultureInfo.InvariantCulture, format, obj));
            }

            private PrintWriter(System.IO.TextWriter w) {
                writer = w;
            }

            public void Dispose() {
                writer.Close();
            }
        }
        #endregion
        #region Scanner
        public class Scanner : IDisposable {
            const int MAX_BUFFER_SIZE = 1024 * 1024 * 16;
            //const string DELIMITER = " \r\n\t";

            System.IO.TextReader stream;
            int pos = 0, len = 0;
            bool endStream = false;
            int BufferSize = MAX_BUFFER_SIZE;
            char[] buffer = new char[MAX_BUFFER_SIZE];

            public enum Option { Buffering, NoBuffering }

            public Scanner(System.IO.TextReader stream, Option bufferingOption) {
                this.stream = stream;
                if (bufferingOption == Option.NoBuffering) BufferSize = 1;
            }

            void ReadBuffer() {
                pos = 0;
                len = stream.ReadBlock(buffer, 0, BufferSize);
                endStream = len == 0;
            }

            void SkipDelimiter() {
                while (!endStream && IsDelimiter(Peek())) NextChar();
            }

            static bool IsDelimiter(char c) {
                return char.IsWhiteSpace(c);
                //return DELIMITER.Contains(c);
            }

            bool Continue(char c) {
                return !endStream && !IsDelimiter(c);
            }

            char Peek() {
                if (pos >= len) ReadBuffer();
                return buffer[pos];
            }

            public char NextChar() {
                if (pos >= len) ReadBuffer();
                return buffer[pos++];
            }

            public string NextString() {
                SkipDelimiter();
                StringBuilder res = new StringBuilder();
                for (char c = NextChar(); Continue(c); c = NextChar()) res.Append(c);
                return res.ToString();
            }

            public int NextInt() {
                SkipDelimiter();
                int res = 0;
                char c = NextChar();
                int sign = 1;
                if (c == '-') { sign = -1; c = NextChar(); }
                for (; Continue(c); c = NextChar())
                    res = res * 10 + (c - '0');
                return sign * res;
            }

            public long NextLong() {
                SkipDelimiter();
                long res = 0;
                char c = NextChar();
                long sign = 1;
                if (c == '-') { sign = -1; c = NextChar(); }
                for (; Continue(c); c = NextChar())
                    res = res * 10 + (c - '0');
                return sign * res;
            }

            public double NextDouble() {
                return double.Parse(NextString(), System.Globalization.CultureInfo.InvariantCulture);
            }

            public int[] NextInts(int n) {
                int[] res = new int[n];
                for (int i = 0; i < n; i++) res[i] = NextInt();
                return res;
            }

            public long[] NextLongs(int n) {
                long[] res = new long[n];
                for (int i = 0; i < n; i++) res[i] = NextLong();
                return res;
            }

            public double[] NextDoubles(int n) {
                double[] res = new double[n];
                for (int i = 0; i < n; i++) res[i] = NextDouble();
                return res;
            }

            public string[] NextStrings(int n) {
                string[] res = new string[n];
                for (int i = 0; i < n; i++) res[i] = NextString();
                return res;
            }

            public static Scanner FromString(string s) {
                return new Scanner(new System.IO.StreamReader(new System.IO.MemoryStream(Encoding.ASCII.GetBytes(s))), Option.Buffering);
            }

            public static Scanner FromFile(string path) {
                return new Scanner(new System.IO.StreamReader(path), Option.Buffering);
            }

            public static Scanner FromConsole() {
                return new Scanner(Console.In, Option.Buffering);
            }

            public void Dispose() {
                stream.Close();
            }
        }
        #endregion
    }
