            List<int> inds = new List<int>();
            List<int> pos = new List<int>();
            int first = 0, last = 0, max = 0, sq = 0;
            for (int i = 0; i < a.Length; i++)
            {
                if (a[i] == '(' || a[i] == '[')
                {
                    stack.Add(a[i]);
                    inds.Add(i);
                }
                else 
                {
                    if (stack.Count > 0)
                    {
                        if ((a[i] == ')' && stack.Last() == '(') || (a[i] == ']' && stack.Last() == '['))
                        {
                            if (pos.Count > 0) 
                            {
                                if (pos.Last() == inds.Last() - 1) { pos[pos.Count - 1] = i; goto next; }
                            }
                            pos.Add(inds.Last());
                            pos.Add(i);
                        next:
                            for (int j = pos.Count - 2; j >= 0; j -= 2)
                            {
                                if (pos[j] > inds.Last()) { pos.RemoveAt(j); pos.RemoveAt(j); j += 2; }
                                else if (pos[j] < inds.Last()) { break; }
                            }
                            stack.RemoveAt(stack.Count - 1);
                            inds.RemoveAt(inds.Count - 1);
                        }
                        else { stack.Clear(); inds.Clear(); }
                    }
                    else { stack.Clear(); inds.Clear(); }
                }
            }
            for (int i = 1; i < pos.Count - 1; i += 2)
            {
                if (pos[i] + 1 == pos[i + 1])
                {
                    pos.RemoveAt(i); pos.RemoveAt(i); i -= 2;
                }
