namespace CodeForces
{
    public class PriorityQueue<TPriority, TItem>
    {
        readonly SortedDictionary<TPriority, Queue<TItem>> _subqueues;
        private int _count = 0;
        public int Count { get { return _count; } }

        public PriorityQueue(IComparer<TPriority> priorityComparer)
        {
            _subqueues = new SortedDictionary<TPriority, Queue<TItem>>(priorityComparer);
        }

        public PriorityQueue() : this(Comparer<TPriority>.Default) { }

        public void Enqueue(TPriority priority, TItem item)
        {
            if (!_subqueues.ContainsKey(priority))
            {
                _subqueues.Add(priority, new Queue<TItem>());
            }

            _subqueues[priority].Enqueue(item);

            _count++;
        }

        public TItem Peek()
        {
            if (HasItems)
                return _subqueues.First().Value.Peek();
            else
                throw new InvalidOperationException("The queue is empty");
        }

        public bool HasItems
        {
            get { return _subqueues.Any(); }
        }

        public TItem Dequeue()
        {
            if (_subqueues.Any())
            {
                KeyValuePair<TPriority, Queue<TItem>> first = _subqueues.First();
                TItem nextItem = first.Value.Dequeue();
                if (!first.Value.Any())
                {
                    _subqueues.Remove(first.Key);
                }
                _count--;
                return nextItem;
            }
            else
                throw new InvalidOperationException("The queue is empty");
        }
    }

    public class LeastCostBracketSequence
    {
        class Cost
        {
            public int Index { get; set; }
            public int Left { get; set; }
            public int Right { get; set; }

            public int GetWeight()
            {
                return Right - Left;
            }
        }

        class CostComparer : IComparer<int>
        {
            public int Compare(int x, int y)
            {
                return -(x.CompareTo(y));
            }
        }

        public static void Main(string[] args)
        {
            var inputs = Console.ReadLine();
            StringBuilder result = new StringBuilder();
            int balance = 0;
            long totalWeight = 0;
            var costs = new PriorityQueue<int, Cost>(new CostComparer());

            for (int i = 0; i < inputs.Length; i++)
            {
                switch (inputs[i])
                {
                    case '(':
                        result.Append(inputs[i]);
                        balance++;
                        break;
                    case ')':
                        result.Append(inputs[i]);
                        balance--;
                        break;
                    case '?':
                        int[] inputs2 = Array.ConvertAll(Console.ReadLine().Split(new[] { ' ' }), int.Parse);
                        var cost = new Cost {Index = i, Left = inputs2[0], Right = inputs2[1]};
                        costs.Enqueue(cost.GetWeight(), cost);
                        result.Append(')');
                        balance--;
                        totalWeight += cost.Right;
                        break;
                }
                if (balance < 0)
                {
                    if (costs.Count == 0)
                    {
                        break;
                    }
                    else
                    {
                        var top = costs.Dequeue();
                        totalWeight += top.Left;
                        totalWeight -= top.Right;
                        result[top.Index] = '(';
                        balance += 2;
                    }
                }
            }
            if (balance != 0)
            {
                Console.WriteLine("-1");
            }
            else
            {
                Console.WriteLine(totalWeight);
                Console.WriteLine(result);
            }
        }
    }
}

