namespace ProgrammingContest.Codeforces.Round47
{
    class C
    {
        static bool LeftRotate(Pair<long, long>[] ps, int len)
        {
            int i = len - 2;
            long x1 = ps[i - 1].first, x2 = ps[i].first, x3 = ps[i + 1].first,
                y1 = ps[i-1].second, y2 = ps[i].second, y3 = ps[i+1].second;
            long cp = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1);
            return cp >= 0;
        }

        static Pair<long, long>[] ConvexHull(Pair<long, long>[] ps)
        {
            if(ps.Length < 3) return ps;
            int ul = 0;
            Pair<long, long>[] upper = new Pair<long, long>[ps.Length];
            upper[ul++] = ps[0]; upper[ul++] = ps[1];
            for (int i = 2; i < ps.Length; i++)
            {
                upper[ul++] = ps[i];
                while (ul >= 3 && LeftRotate(upper, ul))
                {
                    upper[ul - 2] = upper[ul - 1];
                    ul--;
                }
            }

            int ll = 0;
            var lower = new Pair<long, long>[ps.Length];
            lower[ll++] = ps[ps.Length - 1]; lower[ll++] = ps[ps.Length - 2];
            for (int i = ps.Length-3; i >= 0; i--)
            {
                lower[ll++] = ps[i];
                while (ll >= 3 && LeftRotate(lower, ll))
                {
                    lower[ll-2] = lower[ll-1];
                    ll--;
                }
            }
            Pair<long, long>[] res = new Pair<long, long>[ul + ll - 2];
            int p = 0;
            for (int i = 0; i < ul; i++) res[p++] = upper[i];
            for (int i = 1; i < ll - 1; i++) res[p++] = lower[i];
            return res;
        }

        public static void Main()
        {
            int n = int.Parse(Console.ReadLine());
            var ps = new Pair<long, long>[n];
            for (int i = 0; i < n; i++)
            {
                int[] xy = Console.ReadLine().Split(' ').Select(s => int.Parse(s)).ToArray();
                ps[i].first = xy[0];
                ps[i].second = xy[1];
            }

            Array.Sort(ps);
            var ps2 = ConvexHull(ps);
#if false
            Console.WriteLine();
            for (int i = 0; i < ps2.Length; i++)
                Console.WriteLine("{0} {1}", ps2[i].first, ps2[i].second);
#endif
            long[] dx = new long[] { 0, 0, -1, 1 }, dy = new long[] { -1, 1, 0, 0 };
            var ps3 = new Pair<long, long>[ps2.Length * 4];
            for (int i = 0; i < ps2.Length; i++)
                for (int j = 0; j < 4; j++)
                {
                    ps3[i * 4 + j].first = ps2[i].first + dx[j];
                    ps3[i * 4 + j].second = ps2[i].second + dy[j];
                }

            Array.Sort(ps3);
            var ps4 = ConvexHull(ps3);

            long res = 0;
            for (int i = 0, m = ps4.Length; i < m; i++)
            {
                long dx_ = Math.Abs(ps4[i].first - ps4[(i + 1) % m].first),
                    dy_ = Math.Abs(ps4[i].second - ps4[(i + 1) % m].second);
                res += Math.Max(dx_, dy_);
            }
            Console.WriteLine(res);
        }

        #region Pair
        public static class Pair
        {
            public static Pair<T1, T2> Create<T1, T2>(T1 t1, T2 t2)
                where T1 : IComparable<T1>, IEquatable<T1>
                where T2 : IComparable<T2>, IEquatable<T2>
            {
                return new Pair<T1, T2>(t1, t2);
            }
        }

        public struct Pair<T1, T2> : IComparable<Pair<T1, T2>>
            where T1 : IComparable<T1>, IEquatable<T1>
            where T2 : IComparable<T2>, IEquatable<T2>
        {
            public T1 first;
            public T2 second;

            public Pair(T1 t1, T2 t2)
            {
                first = t1;
                second = t2;
            }

            public static bool operator <(Pair<T1, T2> lhs, Pair<T1, T2> rhs)
            {
                int comp = lhs.first.CompareTo(rhs.first);
                if (comp < 0 || comp == 0 && lhs.second.CompareTo(rhs.second) < 0) return true;
                return false;
            }

            public static bool operator >(Pair<T1, T2> lhs, Pair<T1, T2> rhs)
            {
                return !(lhs < rhs || lhs == rhs);
            }

            public static bool operator ==(Pair<T1, T2> lhs, Pair<T1, T2> rhs)
            {
                return lhs.first.Equals(rhs.first) && lhs.second.Equals(rhs.second);
            }

            public static bool operator !=(Pair<T1, T2> lhs, Pair<T1, T2> rhs)
            {
                return !(lhs == rhs);
            }

            public int CompareTo(Pair<T1, T2> p)
            {
                if (this < p) return -1;
                if (this > p) return 1;
                return 0;
            }

            public override bool Equals(object obj)
            {
                return base.Equals(obj);
            }
