    class Rational
    {
        public long bunsi, bunbo;
        public Rational(long bunbo, long bunsi)
        {
            long g = gcd(bunsi, bunbo);
            if (g != 0)
            {
                this.bunsi = bunsi / g;
                this.bunbo = bunbo / g;
            }
            if (this.bunbo < 0)
            {
                this.bunbo = -this.bunbo;
                this.bunsi = -this.bunsi;
            }
        }

        public bool eq(Rational r) { return bunsi == r.bunsi && bunbo == r.bunbo; }
        static long gcd(long n, long r) { if (r == 0) return n; return gcd(r, n % r); }
    }
    class D
    {
        static int n;
        static int[] xs;

        static long gcd(long n, long r) { if (r == 0) return n; return gcd(r, n % r); }

        static bool ok(Rational r, long a, long b)
        {
            long c = r.bunsi*a;
            long g = gcd(c, r.bunbo);
            if (g == 0) return b == 0;
            if (r.bunbo != g) return false;
            return c / g == b;
        }

        static int check(int start, Rational r, bool rec)
        {
            if (r.bunbo == 0 && r.bunsi != 0) return 2;
            //Console.WriteLine("{0} / {1}", r.bunsi, r.bunbo);
            for (int i = start; i < n - 1; i++)
            {
                if (ok(r, xs[i], xs[i + 1])) continue;
                if (!rec) return 2;
                if (i + 2 >= n) return 1;
                int res = 2;
                if (i == 0 && ok(r, xs[i + 1], xs[i + 2]) || ok(r, xs[i], xs[i + 2]))
                {
                    res = Math.Min(res, check(i + 2, r, false) + 1);
                }
                return res;
            }
            return 0;
        }

