﻿using System;
using System.IO;
using System.Text;

namespace Round_Table_Knights
{
    internal class Program
    {
        private static readonly StreamReader reader = new StreamReader(Console.OpenStandardInput(1024*10), Encoding.ASCII, false, 1024*10);
        private static readonly StreamWriter writer = new StreamWriter(Console.OpenStandardOutput(1024*10), Encoding.ASCII, 1024*10);
        private static int[] nn;

        private static void Main(string[] args)
        {
            int n = Next();

            nn = new int[n];
            for (int i = 0; i < n; i++)
            {
                nn[i] = Next();
            }

            for (int i = 1; i*i <= n; i++)
            {
                if (n%i == 0)
                {
                    if (n/i >= 3 && Check(i))
                    {
                        writer.WriteLine("YES");
                        writer.Flush();
                        return;
                    }
                    if (i >= 3 && i*i != n && Check(n/i))
                    {
                        writer.WriteLine("YES");
                        writer.Flush();
                        return;
                    }
                }
            }

            writer.WriteLine("NO");
            writer.Flush();
        }

        private static bool Check(int k)
        {
            for (int i = 0; i < k; i++)
            {
                bool ok = true;
                for (int j = i; j < nn.Length; j += k)
                {
                    if (nn[j] == 0)
                    {
                        ok = false;
                        break;
                    }
                }
                if (ok)
                    return true;
            }
            return false;
        }

        private static int Next()
        {
            int c;
            int res = 0;
            do
            {
                c = reader.Read();
                if (c == -1)
                    return res;
            } while (c < '0' || c > '9');
            res = c - '0';
            while (true)
            {
                c = reader.Read();
                if (c < '0' || c > '9')
                    return res;
                res *= 10;
                res += c - '0';
            }
        }
    }
}

using System;
using System.Collections.Generic;

public class Program {
    private int n;
    private int[] numbers;

    public void Solve() {
        string[] data;
        data = Console.ReadLine().Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        n = int.Parse(data[1]);
        data = Console.ReadLine().Split(new char[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
        numbers = new int[data.Length];
        for (int i = 0; i < numbers.Length; ++i)
            numbers[i] = int.Parse(data[i]);
        Console.WriteLine(computeMinCost());
    }

    private int computeMinCost() {
        Array.Sort(numbers);
        if (numbers.Length > 0 && numbers[0] == 1)
            return n == 2 ? 0 : 1;
        else if (n >= limit)
            return -1;
        int cost = 0, index = 0;
        foreach (int prime in primes) {
            if (prime >= n)
                break;
            while (index < numbers.Length && numbers[index] < prime)
                ++index;
            if (index == numbers.Length || numbers[index] != prime)
                return -1;
            ++cost;
        }
        return cost;
    }

    private static int limit = 1299744;
    private static bool[] isPrime;
    private static List<int> primes;

    private static void computePrimes() {
        isPrime = new bool[limit];
        for (int i = 2; i < limit; ++i)
            isPrime[i] = true;
        primes = new List<int>();
        for (int i = 2; i < limit; ++i) {
            if (isPrime[i])
                primes.Add(i);
            foreach (int prime in primes) {
                if (i * prime >= limit)
                    break;
                isPrime[i * prime] = false;
                if (i % prime == 0)
                    break;
            }
        }
    }

    public static void Main() {
        computePrimes();
        new Program().Solve();
    }
}

