type OldList []*Driver
type NewList []*Driver
func (list OldList) Len() int {
  return len(list)
}
func (list OldList) Swap(i, j int) {
  list[i], list[j] = list[j], list[i]
}
func (list NewList) Len() int {
  return len(list)
}
func (list NewList) Swap(i, j int) {
  list[i], list[j] = list[j], list[i]
}

func (list OldList) Less(i, j int) bool {
  a, b := list[i], list[j]
  if a.Points != b.Points {
    return a.Points > b.Points
  }
  return comparePlaces(a, b)
}
func (list NewList) Less(i, j int) bool {
  a, b := list[i], list[j]
  if a.Places[1] != b.Places[1] {
    return a.Places[1] > b.Places[1]
  }
  if a.Points != b.Points {
    return a.Points > b.Points
  }
  return comparePlaces(a, b)
}
func comparePlaces(a, b *Driver) bool {
  for p := 1; p <= a.MaxPlace || p <= b.MaxPlace; p++ {
    placesA := a.Places[p]
    placesB := b.Places[p]
    if placesA != placesB {
      return placesA > placesB
    }
  }
  return true
}

