    for ni := 0; ni < n; ni++ {
      name := getS()
      place := ni+1
      driver, found := drivers[name]
      if !found {
        driver = &Driver{ name, 0, map[int]int{}, 0 }
        drivers[name] = driver
      }
      driver.Points += points[place]
      driver.Places[place] += 1
      if place > driver.MaxPlace {
        driver.MaxPlace = place
      }
    }
  }
  oldList, newList := []*Driver{}, []*Driver{}
  for _, driver := range drivers {
    oldList = append(oldList, driver)
    newList = append(newList, driver)
