	var t int64
	res := make([]int64, 0, n)
	for i := 0; i < n; i++ {
		fmt.Fscanf(io.in, "%d", &t)
		res = append(res, t)
	}
	fmt.Fscanf(io.in, "\n")
	return res
}

type log struct {
	s string
	i int
}

var errOutOfRange = errors.New("out of range")

func (l *log) left() (bool, error) {
	if l.i >= len(l.s) {
		return false, errOutOfRange
	}
	c := l.s[l.i]
	l.i++
	return c == '0', nil
}

func mergeSort(a []int, l *log) error {
	if len(a) == 1 {
		return nil
	}

	err := mergeSort(a[:len(a)/2], l)
	if err != nil {
		return err
	}

	err = mergeSort(a[len(a)/2:], l)
	if err != nil {
		return err
	}

	b := make([]int, 0, len(a))
	i, j := 0, len(a)/2

	for i < len(a)/2 && j < len(a) {
		left, err := l.left()
		if err != nil {
			return err
		}

		if left {
			b = append(b, a[i])
			i++
		} else {
			b = append(b, a[j])
			j++
		}
	}

	for i < len(a)/2 {
		b = append(b, a[i])
		i++
	}

	for j < len(a) {
		b = append(b, a[j])
		j++
	}

	for i := range b {
		a[i] = b[i]
	}
	return nil
}

func doSomething(n int, s string) int {
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = i
	}

	l := log{s, 0}
	err := mergeSort(a, &l)
	if err != nil {
		return 1000000000
	}

	return len(l.s) - l.i
}

func doSomethingWithPrint(n int, s string) int {
	a := make([]int, n)
	for i := 0; i < n; i++ {
		a[i] = i
	}

	l := log{s, 0}
	err := mergeSort(a, &l)
	if err != nil {
		return 1000000000
	}

	if _, err = l.left(); err != nil {
		b := make([]int, len(a))

		for i, v := range a {
			b[v] = i + 1
		}

		fmt.Println(len(a))
		for _, v := range b {
			fmt.Printf("%d ", v)
		}
	}

	return len(l.s) - l.i
}

func main() {
	io := NewIO(os.Stdin, os.Stdout)
	s := io.ReadString()

	l, r := 1, 200000

	for r - l > 1 {
		x1 := l + (r - l) / 3
		x2 := l + (r - l) / 3 * 2

		v1 := doSomething(x1, s)
		v2 := doSomething(x2, s)

		if v1 < v2 {
			l = x1
		} else {
			r = x2
		}
	}

	doSomethingWithPrint(l, s)
}

