func min(x int, y int) int {
	if x < y {
		return x
	}
	return y
}

func main() {
	bufin = bufio.NewReader(os.Stdin)
	bufout = bufio.NewWriter(os.Stdout)
	defer bufout.Flush()

	fmt.Fscan(bufin, &n)
	for i := 1; i <= n; i++ {
		fmt.Fscan(bufin, &a[i])
	}

	for j := 0; j < 3; j++ {
		f[0][j] = 0
	}

	for i := 1; i <= n; i++ {
		f[i][0] = n
		for j := 0; j < 3; j++ {
			f[i][0] = min(f[i][0], f[i-1][j]+1)
		}

		f[i][1] = n
		if (a[i] & 1) == 1 {
			f[i][1] = min(f[i][1], f[i-1][0])
			f[i][1] = min(f[i][1], f[i-1][2])
		}

		f[i][2] = n
		if ((a[i] >> 1) & 1) == 1 {
			f[i][2] = min(f[i][2], f[i-1][0])
			f[i][2] = min(f[i][2], f[i-1][1])
