func reverse(s string) string {
	b := []byte(s)
	for i, j := 0, len(b)-1; i < j; i, j = i+1, j-1 {
		b[i], b[j] = b[j], b[i]
	}
	return string(b)
}

func main() {
	bs, _ := ioutil.ReadAll(os.Stdin)
	reader := bytes.NewBuffer(bs)

	var s, s0, s1 string
	var forward, backward bool

	fmt.Fscanf(reader, "%s\n", &s)
	fmt.Fscanf(reader, "%s\n", &s0)
	fmt.Fscanf(reader, "%s", &s1)

	findex0 := strings.Index(s, s0)
	findex1 := strings.LastIndex(s, s1)
	if findex0 == -1 || findex1 == -1 || findex1-findex0 < len(s0) {
		forward = false
	} else {
		forward = true
	}

	s = reverse(s)
	bindex0 := strings.Index(s, s0)
	bindex1 := strings.LastIndex(s, s1)
	if bindex0 == -1 || bindex1 == -1 || bindex1-bindex0 < len(s0) {
		backward = false
	} else {
		backward = true
	}

	if forward && backward {
		fmt.Printf("both\n")
	} else if forward && !backward {
		fmt.Printf("forward\n")
	} else if !forward && backward {
		fmt.Printf("backward\n")
	} else {
		fmt.Printf("fantasy")
	}
}

