	var a, v, l, d, w float64
	scanf("%f %f\n", &a, &v)
	scanf("%f %f %f\n", &l, &d, &w)

	if v > w {
		if s := w * w / 2 / a; s <= d {
			peak := math.Sqrt(a*d + w*w/2)
			t1 := 0.0
			if peak <= v {
				t1 = (2*peak - w) / a
			} else {
				t1 = (2*v-w)/a + (d-(v*v-w*w/2)/a)/v
			}
			printf("%.6f\n", t1+getTime(w, v, a, l-d))
		} else {
