		}
	} else {
		printf("%.6f\n", getTime(0, v, a, l))
	}
}

func getTime(v0, maxV, a, l float64) float64 {
	if s := (maxV*maxV - v0*v0) / 2 / a; s <= l {
		return (maxV-v0)/a + (l-s)/maxV
	}
	return (math.Sqrt(v0*v0+2*a*l) - v0) / a
}

