	Fscan(in, &n)
	g := make([][]int, n)
	for i := 1; i < n; i++ {
		Fscan(in, &v, &w)
		v--
		w--
		g[v] = append(g[v], w)
		g[w] = append(g[w], v)
	}

	pa := make([][3000]int16, n)
	sz := make([][3000]int16, n)
	for i := range pa {
		var f func(int16, int16)
		f = func(v, fa int16) {
			pa[i][v] = fa
			sz[i][v] = 1
			for _, w := range g[v] {
				if w := int16(w); w != fa {
					f(w, v)
					sz[i][v] += sz[i][w]
				}
			}
		}
		f(int16(i), -1)
	}

	dp := make([][3000]int64, n)
	var f func(int16, int16) int64
	f = func(v, w int16) int64 {
		if v == w {
			return 0
		}
		if dp[v][w] == 0 {
			dp[v][w] = max(f(pa[w][v], w), f(v, pa[v][w])) + int64(int(sz[v][w])*int(sz[w][v]))
		}
		return dp[v][w]
	}
	ans := int64(0)
	for v := int16(0); v < int16(n); v++ {
		for w := v + 1; w < int16(n); w++ {
			ans = max(ans, f(v, w))
		}
	}
