)

var n, m int
var vType []Type
var edges [][]int

func main() {
	defer out.Flush()
	fmt.Fscan(in, &n, &m)
	vType = make([]Type, n)
	edges = make([][]int, n)
	for i := 0; i < m; i++ {
		var a, b int
		fmt.Fscan(in, &a, &b)
		a--
		b--
		edges[a] = append(edges[a], b)
		edges[b] = append(edges[b], a)
	}
	if solve() {
		fmt.Fprintln(out, "Yes")
		for v := range vType {
			fmt.Fprint(out, string('a'+vType[v]-1))
		}
		fmt.Fprintln(out)
	} else {
		fmt.Fprintln(out, "No")
	}
}

func solve() bool {
	for v := range edges {
		if len(edges[v]) == n-1 {
			vType[v] = B
		}
	}
	for v := range vType {
		if vType[v] == UNSEEN {
			mark(v, A)
			break
		}
	}
	for v := range vType {
		if vType[v] == UNSEEN {
			mark(v, C)
			break
		}
	}
	var a, b, c int
	for v := range vType {
		switch vType[v] {
		case UNSEEN:
			return false
		case A:
			a++
		case B:
			b++
		case C:
			c++
		}
	}
	for v := range vType {
		if vType[v] == A && len(edges[v]) != a-1+b {
			return false
		}
		if vType[v] == C && len(edges[v]) != c-1+b {
			return false
		}
	}
	return true
}

func mark(v int, t Type) {
	if vType[v] != UNSEEN {
		return
	}
	vType[v] = t
	for _, u := range edges[v] {
		mark(u, t)
	}
}

type Type int

const (
	UNSEEN Type = iota
	A
	B
	C
)

package main

import "fmt"

var (
	n           int
	num         []int64
	par         []int
	rem         []int64
	minCount    int = 1e9
	delimsCache     = make(map[int64]int)
)

func countPrimeDelims(n int64) (count int) {
	if val, ok := delimsCache[n]; ok {
		count = val
		return
	}
	n0 := n
	for ; n%2 == 0; n /= 2 {
		count++
	}
	for p := int64(3); p*p <= n; p += 2 {
		for ; n%p == 0; n /= p {
			count++
		}
	}
	if n > 1 {
		count++
	}
	delimsCache[n0] = count
	return
}

func eval() {
	count := 0
	withPar0 := 0
	for p := 1; p <= n; p++ {
		delimCount := countPrimeDelims(rem[p])
		if delimCount == 1 && num[p] == rem[p] { // rem[p] is prime and p does not have kids
			count += 1
		} else {
			count += delimCount + 1
		}
		if par[p] == 0 {
			withPar0++
		}
	}
	if withPar0 > 1 {
		count++
	}
	if count < minCount {
		minCount = count
	}
}

func brute(i int) {
	if i == n+1 {
		eval()
		return
	}
	par[i] = 0
	brute(i + 1)

	for p := 1; p <= n; p++ {
		if p != i && num[i] <= rem[p] && rem[p]%num[i] == 0 {
			par[i] = p
			rem[p] /= num[i]
			brute(i + 1)
			rem[p] *= num[i]
		}
	}
}

func main() {
	fmt.Scan(&n)
	num = make([]int64, n+1)
	par = make([]int, n+1)
	rem = make([]int64, n+1)
	for i := 1; i <= n; i++ {
		fmt.Scan(&num[i])
		rem[i] = num[i]
	}
	brute(1)
	fmt.Println(minCount)
}

