	}
	b := make([]int, lb)
	bPos := make([]int, 1e6+1)
	for i := range b {
		fmt.Fscan(in, &b[i])
		bPos[b[i]] = i + 1
	}

	ans := 0
	wrapped := false
	var i, j int
	for i < la && j - i < la {
		if bPos[a[j%la]] == 0 {
			j++
			i = j
			wrapped = false
			continue
		}
		if i == j {
			j++
			if ans < j-i {
				ans = j - i
			}
		}
		for j-i < la {
			if bPos[a[j%la]] == 0 {
				break
			}
			if bPos[a[j%la]] < bPos[a[(j-1)%la]] && (wrapped || bPos[a[i]] < bPos[a[j%la]]) || wrapped && bPos[a[i]] < bPos[a[j%la]] {
				if bPos[a[i]] > bPos[a[(i+1)%la]] {
					wrapped = false
				}
				i++
				break
			}
			if bPos[a[j%la]] < bPos[a[(j-1)%la]] {
				wrapped = true
			}
