func diminish(count []int, k int) bool {
	for d := k; d < 10; d += 3 {
		if count[d] > 0 {
			count[d] -= 1
			return true
		}
	}
	return false
}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Split(bufio.ScanWords)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()
	n := scanInt(scanner)
	count := make([]int, 10)
	sum := 0
	for i := 0; i < n; i++ {
		x := scanInt(scanner)
		count[x] += 1
		sum += x
	}
	if count[0] == 0 {
		writer.WriteString("-1\n")
		return
	}
	if sum%3 == 1 {
		if !diminish(count, 1) {
			if !diminish(count, 2) || !diminish(count, 2) {
				writer.WriteString("0\n")
				return
			}
		}
	} else if sum%3 == 2 {
		if !diminish(count, 2) {
			if !diminish(count, 1) || !diminish(count, 1) {
				writer.WriteString("0\n")
				return
			}
		}
	}
	max := 0
	for d := 0; d < 10; d++ {
		if count[d] > 0 {
			max = d
		}
	}
	if max == 0 {
		writer.WriteString("0\n")
		return
	}
	for d := 9; d >= 0; d-- {
		for i := 0; i < count[d]; i++ {
			writer.WriteString(fmt.Sprintf("%d", d))
		}
	}
	writer.WriteString("\n")
}

