)

type point struct {
	x, y int64
}

func counterclockwiseTurn(a, b, c point) bool {
	ab := point{b.x - a.x, b.y - a.y}
	ac := point{c.x - a.x, c.y - a.y}
	return ab.x*ac.y-ab.y*ac.x > 0
}

func convexHull(points []point) []point {
	sort.Slice(points, func(i, j int) bool {
		if points[i].x == points[j].x {
			return points[i].y < points[j].y
		}
		return points[i].x < points[j].x
	})

	var lower []point
	for i := len(points) - 1; i >= 0; i-- {
		for len(lower) >= 2 && counterclockwiseTurn(lower[len(lower)-2], lower[len(lower)-1], points[i]) {
			lower = lower[:len(lower)-1]
		}
		lower = append(lower, points[i])
	}

	var upper []point
	for i := range points {
		for len(upper) >= 2 && counterclockwiseTurn(upper[len(upper)-2], upper[len(upper)-1], points[i]) {
			upper = upper[:len(upper)-1]
		}
		upper = append(upper, points[i])
	}

	return append(lower[:len(lower)-1], upper[:len(upper)-1]...)
}

var in = bufio.NewReaderSize(os.Stdin, 2<<16)

func readPoints() []point {
	var n int
	fmt.Fscan(in, &n)
	a := make([]point, n)
	for i := range a {
		fmt.Fscan(in, &a[i].x, &a[i].y)
	}
	return a
}

func solve() bool {
	a := readPoints()
	b := readPoints()
	hull := convexHull(append(b, a...))
	if len(hull) != len(a) {
		return false
	}
	start := 0
	for start < len(hull) && hull[start] != a[0] {
		start++
	}
	if start == len(hull) {
		return false
	}
	for i := range a {
		if a[i] != hull[(i+start)%len(hull)] {
			return false
		}
	}
	return true
}

func main() {
	if solve() {
		fmt.Println("YES")
	} else {
		fmt.Println("NO")
	}
}

