	for i := uint64(1); i*i <= r; i++ {
		if ok(i, l, r, k) {
			if i > found {
				found = i
			}
		}
		if ok(r/i, l, r, k) {
			if r/i > found {
				found = r / i
			}
		}
	}
	if found <= 2 {
		fmt.Println(1 % m)
		return
	}
	matrix := newMatrix(2, 2)
