			return errors.New("fail")
		}
	}

	if ok1 {
		if op1 == "fail" {
			return errors.New("fail")
		}
		if (op == "-" && (op1 == "-" || op1 == "+")) || (op == "/" && (op1 == "/" || op1 == "*")) ||
			((op == "*" || op == "/") && (op1 == "+" || op1 == "-")) {
			return errors.New("fail")
		}
	}
	return nil
}

func getOp(tokens []string) string {

	if len(tokens) == 1 {
		rank, ok := macro2Op[tokens[0]]
		if ok {
			return rank
		} else {
			return "()"
		}
	}

	op := make([]string, 10000, 10000)
	num := make([]string, 10000, 10000)
	opPointer, numPointer := 0, 0
	ret := ""

	for i := 0; i < len(tokens); i++ {
		if tokens[i] == "(" {
			op[opPointer] = "("
			opPointer++
		} else if tokens[i] == "+" || tokens[i] == "-" {
			for opPointer != 0 {
				if op[opPointer-1] == "*" || op[opPointer-1] == "/" || op[opPointer-1] == "+" || op[opPointer-1] == "-" {
					err := check(num[numPointer-2], num[numPointer-1], op[opPointer-1])
					if err != nil {
						return "fail"
					}
					ret = op[opPointer-1]
					numPointer--
					num[numPointer-1] = "1"
					opPointer--
				} else {
					break
				}
			}
			op[opPointer] = tokens[i]
			opPointer++
		} else if tokens[i] == "*" || tokens[i] == "/" {
			for opPointer != 0 {
				if op[opPointer-1] == "*" || op[opPointer-1] == "/" {
					err := check(num[numPointer-2], num[numPointer-1], op[opPointer-1])
					if err != nil {
						return "fail"
					}
					ret = op[opPointer-1]
					numPointer--
					num[numPointer-1] = "1"
					opPointer--
				} else {
					break
				}
			}
			op[opPointer] = tokens[i]
			opPointer++
		} else if tokens[i] == ")" {
			for opPointer != 0 {
				if op[opPointer-1] == "*" || op[opPointer-1] == "/" || op[opPointer-1] == "+" || op[opPointer-1] == "-" {
					err := check(num[numPointer-2], num[numPointer-1], op[opPointer-1])
					if err != nil {
						return "fail"
					}
					numPointer--
					num[numPointer-1] = "1"
					opPointer--
				} else if op[opPointer-1] == "(" {
					opPointer--
					break
				}
			}
			rank, ok := macro2Op[num[numPointer-1]]
			if ok && rank == "fail" {
				return rank
			} else {
				num[numPointer-1] = "1"
			}
			ret = "()"
		} else {
			num[numPointer] = tokens[i]
			numPointer++
		}
	}
	for opPointer != 0 {
		err := check(num[numPointer-2], num[numPointer-1], op[opPointer-1])
		if err != nil {
			return "fail"
		}
		ret = op[opPointer-1]
		numPointer--
		num[numPointer-1] = "1"
		opPointer--
	}

	return ret
}

func tokenize(s string) []string {
	tokens := make([]string, 0, 200)
	b := []byte(s)
	token := make([]byte, 0, 100)
	for i := 0; i < len(b); i++ {
		if b[i] == '(' || b[i] == ')' ||
			b[i] == '+' || b[i] == '-' || b[i] == '*' || b[i] == '/' ||
			b[i] == '\r' || b[i] == '\n' || b[i] == ' ' {
			if len(token) != 0 {
				tokens = append(tokens, string(token))
				token = make([]byte, 0, 100)
			}
			if b[i] != ' ' && b[i] != '\r' && b[i] != '\n' {
				tokens = append(tokens, string([]byte{b[i]}))
			}
		} else {
			token = append(token, b[i])
		}
	}
	return tokens
}

