var calculateTrees = function (cont, startRow, endRow, startCol, endCol) {
    let ans = 0;
    for (let i = startRow; i < endRow; i++)
        for (let j = startCol; j < endCol; j++)
            ans += cont[i][j];

    //console.log(" startRow=%d  endRow=%d  startCol=%d  endCol=%d   ans=%d",startRow, endRow, startCol, endCol,ans);
    return ans;
}

var indicator = 0, N, M, temp, cont = [], HouseX, HouseY;
rl.on('line', (input) => {
    if (indicator == 0) {
        temp = input.split(" ").map(item => parseInt(item));
        N = temp[0];
        M = temp[1];
        indicator++;
    }
    else if (indicator <= N) {
        cont.push(input.split(" ").map(item => parseInt(item)));
        indicator++;
    }
    else {
        temp = input.split(" ").map(item => parseInt(item));
        HouseX = temp[0];
        HouseY = temp[1];
    }
}).on('close', () => {
    let ans = N * M, helper;
    for (let i = 0; i < N; i++) {
        for (let j = 0; j < M; j++) {
            if (i + HouseX <= N && j + HouseY <= M) {
                helper = calculateTrees(cont, i, i + HouseX, j, j + HouseY);
                if (ans > helper)
                    ans = helper;
            }
            if (i + HouseY <= N && j + HouseX <= M) {
                helper = calculateTrees(cont, i, i + HouseY, j, j + HouseX);
                if (ans > helper)
                    ans = helper;
            }
        }
    }
    console.log(ans);
});

