              if(t%2) dp[2][y][t+1]+=dp[1][h][t];
              else dp[2][y][t]+=dp[1][h][t];
            }
          }
          else{
              if(t%2){
              if(h>y) dp[x][y][t]+=dp[x-1][h][t];
              else if(h<y) dp[x][y][t+1]+=dp[x-1][h][t];
              }
              else{
              if(h<y) dp[x][y][t]+=dp[x-1][h][t];
              else if(h>y) dp[x][y][t+1]+=dp[x-1][h][t];
              }
          }
    }

    if(t*2+1>n||n>6*t+1) return 0;
    let ans=0;
    for(let i=1;i<=4;i++)
    ans+=dp[n][i][2*t-1];
    return ans;
}

'use strict';

function solve(n, m, s) {
  const diff = new Array(n + 2).fill(0);
  for (let str of s) {
    const num = Number(str.slice(1));
    if (str[0] === '+') {
      diff[num]++;
      diff[num + 1]--;
    } else {
      diff[0]++;
      diff[num]--;
      diff[num + 1]++;
      diff[n + 1]--;
    }
  }
  const suspects = new Set();
  let sum = diff[0];
  for (let i = 1; i <= n; i++) {
    sum += diff[i];
    if (sum === m) suspects.add(i);
  }
  const res = new Array(n);
  for (let i = 0; i < n; i++) {
    const str = s[i];
    const num = Number(str.slice(1));
    if (str[0] === '+') {
      if (suspects.has(num)) {
        if (suspects.size === 1) res[i] = 'Truth';else res[i] = 'Not defined';
      } else {
        res[i] = 'Lie';
      }
    } else {
      if (suspects.has(num)) {
        if (suspects.size === 1) res[i] = 'Lie';else res[i] = 'Not defined';
      } else {
        res[i] = 'Truth';
      }
    }
  }
  return res.join('\n');
}

