private class DisjointSets {
  private val parents = mutableMapOf<Position, Position>()
  private val ranks = mutableMapOf<Position, Int>()

  var groupCount = 0
    private set

  val positions get() = parents.keys

  operator fun plusAssign(pos: Position) {
    if (pos in parents) return

    parents += pos to pos
    ranks += pos to 0
    groupCount++
  }

  fun union(u: Position, v: Position): Position {
    var smallRep = find(u)
    var bigRep = find(v)
    if (smallRep == bigRep) return bigRep

    if (ranks[smallRep] > ranks[bigRep]) {
      smallRep = bigRep.also { bigRep = smallRep }
    }

    parents[smallRep] = bigRep
    if (ranks[smallRep] == ranks[bigRep]) ranks[bigRep] = ranks[bigRep]!! + 1
    groupCount--
    return bigRep
  }

  fun find(u: Position): Position {
    if (u != parents[u]) {
      parents[u] = find(parents[u]!!)
    }

    return parents[u]!!
  }
}

private data class Position(
  val x: Int,
  val y: Int,
)

private var debugMode: Boolean = false

fun start(
  inStream: InputStream = System.`in`,
  outStream: OutputStream? = null,
  debugModeEnabled: Boolean = false
) {
  debugMode = debugModeEnabled

  useWith(outStream.toPrintStream()) {
    useWith(inStream.bufferedReader(Charsets.ISO_8859_1)) {
      val nPositions = nextLine.toInt()
      val ds = DisjointSets()

      repeat(nPositions) {
        val (x, y) = nextLine.toInts()
        val pos = Position(x, y)
        ds += pos
      }

      val horReps = mutableMapOf<Int, Position>()
      val verReps = mutableMapOf<Int, Position>()
      for (pos in ds.positions) {
        val horRep = horReps[pos.x]
        horReps[pos.x] = if (horRep == null) {
          pos
        } else {
          // merge new position to horRep
          ds.union(pos, horRep)
        }

        val verRep = verReps[pos.y]
        verReps[pos.y] = if (verRep == null) {
          pos
        } else {
          // merge new position to verRep
          ds.union(pos, verRep)
        }
      }

      print(ds.groupCount - 1)
    }
  }
}

