fun main() {
    val n = readLine()!!.toInt()
    val matrix = Array(n) { Array(n) { 0 } }
    for (i in 0 until n) {
        matrix[i] = readLine()!!.split(" ").map { it.toInt() }.toTypedArray()
    }
    val middleRowSum = matrix[n / 2].sum()
    val middleColumnSum = matrix.map { row -> row[n / 2] }.sum()
    val primaryDiagSum = matrix.mapIndexed { rowIndex, row -> row[rowIndex] }.sum()
    val secondaryDiagSum = matrix.mapIndexed { rowIndex, row -> row[n - rowIndex - 1] }.sum()
    val centerCell = matrix[n / 2][n / 2]
    println(middleRowSum + middleColumnSum + primaryDiagSum + secondaryDiagSum - 3 * centerCell)
}

