fun dif(a: Int, b: Int) : Int {
  val x = a - b
  return (if (x / 10 == 0) 0 else 1) + (if (x % 10 == 0) 0 else 1)
}

fun solve(start: Int, end: Int, num: Int) : Int {
  var minDif = 3
  var minv = -1
  for (i in start..end) {
    var d = dif(i, num)
    if (d < minDif) {
      minDif = d
      minv = i
    }
  }
  return minv
}

