import java.util.*

class TaskA {
    var n = 0
    var m = 0
    lateinit var prices: IntArray
    lateinit var match: Array<BooleanArray>

    var minimalPrice = -1

    fun run() {
        for (i in 0 until n) {
            for (j in 0 until n) {
                if (i == j) continue
                if (!isMatch(i, j)) continue

                for (k in 0 until n) {
                    if (i == k || j == k) continue
                    if (!isMatch(i, k) || !isMatch(j, k)) continue

                    val price = prices[i] + prices[j] + prices[k]
                    if (minimalPrice == -1) minimalPrice = price
                    if (minimalPrice > price) minimalPrice = price
                }
            }
        }
    }

    private fun isMatch(i: Int, j: Int) = match[i][j]

    fun print() {
        println(minimalPrice)
    }
}

fun task(init: TaskA.() -> Unit): TaskA {
    val t = TaskA()
    t.init()
    return t
}

