class Graph(val nodeCap: Int, edges: Int = nodeCap * 2) {
    var idx = -1
    val first = IntArray(nodeCap) { -1 }
    val edgeCap = edges
    val to = IntArray(edgeCap)
    val from = IntArray(edgeCap)
    val next = IntArray(edgeCap)

    fun addEdge(from: Int, to: Int): Int {
        val edgeId = ++idx
        this.from[edgeId] = from
        this.to[edgeId] = to
        this.next[edgeId] = first[from]
        first[from] = edgeId
        return edgeId
    }

    inline fun edges(u: Int, withEdgeId: Graph.(Int) -> Unit = { }) {
        var id = first[u]
        while (id != -1) {
            withEdgeId.invoke(this, id)
            id = next[id]
        }
    }

    inline fun edges(withEdgeId: Graph.(Int) -> Unit = { }) {
        for (id in 0..idx) {
            withEdgeId.invoke(this, id)
        }
    }
}

fun solve() {
    val n = rd.ni()
    val graph = Graph(n, n - 1 + n - 1)
    val reversed = BooleanArray(graph.edgeCap)
    for (i in 0 until n - 1) {
        val (u, v) = rd.ni() - 1 to rd.ni() - 1
        graph.addEdge(u, v)
        reversed[graph.addEdge(v, u)] = true
    }
    fun calc(u: Int, fa: Int): Int {
        var res = 0
        graph.edges(u) { id ->
            val v = to[id]
            if (v == fa) return@edges
            res += calc(v, u) + if (reversed[id]) 1 else 0
        }
        return res
    }
    val ans = IntArray(n)
    ans[0] = calc(0, -1)
    var min = ans[0]
    fun dp(u: Int, fa: Int) {
        min = minOf(min, ans[u])
        graph.edges(u) { id ->
            val v = to[id]
            if (v == fa) return@edges
            ans[v] = ans[u] + if (reversed[id]) -1 else 1
            dp(v, u)
        }
    }
    dp(0, -1)
    wt.println(min)
    for (i in 0 until n) {
        if (ans[i] == min) {
            wt.print(i + 1)
            wt.print(' ')
        }
    }
    wt.println()
}

