inline fun IntArray.sortWith(comparator: (Int, Int) -> Int, temp: IntArray = IntArray(this.size)) {
    this.sortWith(comparator, 0, this.size, temp)
}

inline fun IntArray.sortWith(comparator: (Int, Int) -> Int, fromIndex: Int = 0, toIndex: Int = size, temp: IntArray = IntArray(toIndex - fromIndex)) {
    val (base, len) = fromIndex to toIndex - fromIndex
    var (range, half) = 2 to 1
    while (half < len) {
        for (i in 0 until len step range) {
            val (st, mid, ed) = intArrayOf(i, minOf(i + half, len), minOf(i + range, len))
            var (l, r, iter) = intArrayOf(st, mid, st)
            while (l < mid || r < ed) {
                if (r >= ed || l < mid && comparator(this[base + l], this[base + r]) <= 0) {
                    temp[iter++] = this[base + l++]
                } else {
                    temp[iter++] = this[base + r++]
                }
            }
            for (j in st until ed) this[base + j] = temp[j]
        }
        half = range
        range = range shl 1
    }
}

