class FastReader(private val input: InputStream, bufCap: Int = 8192) {
    private val buf = ByteArray(bufCap)

    private var len = 0
    private var ptr = 0

    fun readByte(): Int {
        if (len == -1) {
            throw InputMismatchException()
        }
        if (ptr >= len) {
            ptr = 0
            try {
                len = input.read(buf)
            } catch (e: IOException) {
                throw InputMismatchException()
            }
            if (len <= 0) {
                return -1
            }
        }
        return buf[ptr++].toInt()
    }

    private fun isSpaceChar(c: Int): Boolean {
        return c !in 33..126
    }

    private fun skip(): Int {
        var b: Int
        while (readByte().also { b = it } != -1 && isSpaceChar(b));
        return b
    }

    fun nd(): Double {
        return ns().toDouble()
    }

    fun nc(): Char {
        return skip().toChar()
    }

    fun ns(): String {
        var b = skip()
        return buildString {
            while (!isSpaceChar(b)) { // when nextLine, (isSpaceChar(b) && b != ' ')
                appendCodePoint(b)
                b = readByte()
            }
        }
    }

    fun ns(n: Int): CharArray {
        val buf = CharArray(n)
        var b = skip()
        var p = 0
        while (p < n && !isSpaceChar(b)) {
            buf[p++] = b.toChar()
            b = readByte()
        }
        return if (n == p) buf else buf.copyOf(p)
    }

    fun na(n: Int): IntArray {
        val a = IntArray(n)
        for (i in 0 until n) {
            a[i] = ni()
        }
        return a
    }

    fun nal(n: Int): LongArray {
        val a = LongArray(n)
        for (i in 0 until n) {
            a[i] = nl()
        }
        return a
    }

    fun nm(n: Int, m: Int): Array<CharArray> {
        val map = Array(n) { CharArray(0) }
        for (i in 0 until n) {
            map[i] = ns(m)
        }
        return map
    }

    fun nmi(n: Int, m: Int): Array<IntArray> {
        val map = Array(n) { IntArray(0) }
        for (i in 0 until n) {
            map[i] = na(m)
        }
        return map
    }

    fun ni(): Int {
        var num = 0
        var b: Int
        var minus = false
        while (readByte().also { b = it } != -1 && !(b >= '0'.code && b <= '9'.code || b == '-'.code));
        if (b == '-'.code) {
            minus = true
            b = readByte()
        }
        while (true) {
            num = if (b >= '0'.code && b <= '9'.code) {
                num * 10 + (b - '0'.code)
            } else {
                return if (minus) -num else num
            }
            b = readByte()
        }
    }

    fun nl(): Long {
        var num: Long = 0
        var b: Int
        var minus = false
        while (readByte().also { b = it } != -1 && !(b >= '0'.code && b <= '9'.code || b == '-'.code));
        if (b == '-'.code) {
            minus = true
            b = readByte()
        }
        while (true) {
            num = if (b >= '0'.code && b <= '9'.code) {
                num * 10 + (b - '0'.code)
            } else {
                return if (minus) -num else num
            }
            b = readByte()
        }
    }
}

