fun getCount(_n:Long, _l:Int):MutableList<Int>
{    
    if (_n ==0L && _l ==0)
        return mutableListOf<Int>()

    var n =if (_n> 0)  _n  else -_n

    val l = _l

    if (l == 1)
    {        
        return mutableListOf(n.toInt())     
    }


    val l1 = get1(l)

    val bDigit = (n / l1).toInt()    
    val tDigit = bDigit + 1

    val solb = getCount(n - l1 * bDigit, l - 1)
    val vb = get1Count(solb) + bDigit * l

    val solt = getCount(l1 * tDigit - n, l - 1)    
    for (i in 0 until solt.size) {
        solt[i] = -solt[i]
    }
    val vt = get1Count(solt) + tDigit * l

    if (vb < vt)
    {
        solb.add(0)
        solb[l-1] = bDigit
        return solb
    }
    else
    {
        solt.add(0)
        solt[l-1] = tDigit
        return solt        
    }


}

