fun maxSelf(self: String, b: String): String {
    return if (self.length < b.length) {
        b
    } else {
        self
    }
}

fun prefixFunction(s: String): IntArray {
    var n = s.length
    var pi = IntArray(n)
    for (i in 1 until n) {
        var j = pi[i - 1]
        while (j > 0 && s[i] != s[j]) {
            j = pi[j - 1]
        }
        if (s[i] == s[j]) {
            j++
        }
        pi[i] = j
    }
    return pi;
}

fun computeAutomaton(_s: String): Array<IntArray> {
    var s = "$_s#"
    var n = s.length
    var pi = prefixFunction(s)
    var aut = Array(n) { IntArray(26) }
    for (i in 0 until n) {
        for (c in 0 until 26) {
            if (i > 0 && 'A' + c != s[i])
                aut[i][c] = aut[pi[i - 1]][c]
            else
                aut[i][c] = i + if ('A' + c == s[i]) 1 else 0
        }
    }
    return aut;
}

private fun PrintWriter.solve() {
    var s1 = read()
    var s2 = read()
    var s3 = read()
    var n1 = s1.length
    var n2 = s2.length
    var n3 = s3.length
    s1 = "#$s1"
    s2 = "#$s2"

    var aut = computeAutomaton(s3)
    var dp = Array(n1 + 1) { Array(n2 + 1) { Array(n3) { "" } } }
    for (i in 1..n1) {
        for (j in 1..n2) {
            for (k in 0 until n3) {
                if (s1[i] == s2[j] && aut[k][s1[i] - 'A'] < n3) {
                    dp[i][j][aut[k][s1[i] - 'A']] = maxSelf(dp[i][j][aut[k][s1[i] - 'A']], dp[i - 1][j - 1][k] + s1[i])
                }
                dp[i][j][k] = maxSelf(dp[i][j][k], dp[i - 1][j][k])
                dp[i][j][k] = maxSelf(dp[i][j][k], dp[i][j - 1][k])
            }
        }
    }

    var ans = ""
    for (k in 0 until n3) {
        ans = maxSelf(ans, dp[n1][n2][k])
    }
    if (ans.isEmpty()) {
        println(0)
    } else {
        println(ans)
    }
}

