private const val MOD = (1e9 + 7).toInt();
private fun add(a: Int, b: Int): Int = (a + b) % MOD
private fun sub(a: Int, b: Int): Int = (a - b + MOD) % MOD
private fun mul(a: Int, b: Int): Int = ((a.toLong() * b) % MOD).toInt()

// Only correct if MOD is prime so that phi(MOD) = MOD - 1.
private fun div(a: Int, b: Int): Int = mul(a, modPow(b, MOD - 2, MOD))

private fun modPow(base: Int, exponent: Int, mod: Int): Int {
    if (exponent == 0) {
        return 1 % mod
    }
    var u = modPow(base, exponent / 2, mod).toLong()
    u = (u * u) % mod
    if (exponent % 2 == 1) {
        u = (u * base) % mod
    }
    return u.toInt()
}

private tailrec fun gcd(a: Int, b: Int): Int {
