private fun zeta(s: String): IntArray {
    val n = s.length
    val z = IntArray(n)
    var x = 0
    var y = 0
    for (i in 1 until n) {
        z[i] = max(0, min(z[i - x], y - i + 1))
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            x = i
            y = i + z[i]
            z[i]++
        }
    }
    return z
}

