private fun <T : Comparable<T>> firstGeq(a: List<T>, x: T): Int {
    var ret = -1
    var jump = a.size
    while (jump >= 1) {
        while (ret + jump < a.size && a[ret + jump] < x) {
            ret += jump
        }
        jump /= 2
    }
    ret++
    return ret
}

private fun <T : Comparable<T>> firstGreater(a: List<T>, x: T): Int {
    var ret = -1
    var jump = a.size
    while (jump >= 1) {
        while (ret + jump < a.size && a[ret + jump] <= x) {
            ret += jump
        }
        jump /= 2
    }
    ret++
    return ret
}

