inline fun just(c: Char) = run {
  when(c) {
    '*', '?', '.' -> -1
    else -> c - '0'
  }
}

inline fun bombable(c: Char) = run {
  when(c) {
    '*', '?' -> true
    else -> false
  }
}

class Solver(stream: InputStream, private val out: java.io.PrintWriter) {
  fun solve() {
    val S = "..${ns()}.."
    val N = S.length
    val dp = Array(N){Array(2){LongArray(2)} }
    dp[1][0][0] = 1

    for (i in 2 until N) {
      for (cur in 0 until 2) {
        if (!bombable(S[i]) && cur == 1) continue
        if (S[i] == '*' && cur == 0) continue

        for (pre in 0 until 2) {
          for (prepre in 0 until 2) {
            val preJust = just(S[i - 1])
            if (preJust != -1 && preJust != cur + prepre) continue

            dp[i][pre][cur] += dp[i - 1][prepre][pre]
            if (dp[i][pre][cur] >= MOD) dp[i][pre][cur] -= MOD
          }
        }
      }
      debug{"DP($i)"}
      debugDim(dp[i])
    }

    val ans = dp[N-1][0][0]
    out.println(ans)
  }













































