        }
    }

    val D = List(k+1) { IntArray(n+1) { Int.MAX_VALUE } }
    val P = List(k+1) { IntArray(n+1) }

    D[0][0] = 0

    for(i in 0 until k) {
        for(j in if(i == 0) 0..0 else i until n) {
            for(l in 1 .. n-j) {
                if(D[i+1].setMin(j+l, D[i][j] + C[j][l])) P[i+1][j+l] = l
            }
        }
    }

    val kf = (0..k).minBy { D[it][n] }!!
    val cost = D[kf][n]
    val pals = Array(kf) { "" }
    var j = n
    for(i in kf downTo 1) {
        val l = P[i][j]
        j -= l
        pals[i-1] = buildString {
            val sub = s.substring(j, j + (l/2))
            append(sub)
            if(l and 1 == 1) append(s[j + l/2])
            append(sub.reversed())
        }
    }

    println(cost)
