object Main {
    data class Edge(val target: Planet, val cost: Int)
    data class Planet(val id: Int,val routes: ArrayList<Edge> = ArrayList(), val delays: HashMap<Int, Int> = HashMap(), var minTime: Int = Int.MAX_VALUE)
    class State  (
        val idPlanet: Int,
        val time: Int
    ): Comparable<State> {
        override fun compareTo(other: State): Int {
            return time - other.time
        }
    }


    internal class Solver(){
        fun solve(input: Parserdoubt){
            val N = input.nextInt()
            val planets = Array(N) {id -> Planet(id)}
            val M = input.nextInt()
            for(m in 1..M){
                val a = input.nextInt() - 1
                val b = input.nextInt() - 1
                val c = input.nextInt()
                planets[a].routes.add(Edge(planets[b], c))
                planets[b].routes.add(Edge(planets[a], c))
            }

            for(i in 0 until N){
                val c = input.nextInt()
                if(c > 0) {
                    var start = input.nextInt()
                    var last = start + 1
                    for (j in 1 until c) {
                        val t = input.nextInt()
                        if(t == last){
                            last = t + 1
                        } else {
                            for(x in start until last)
                                planets[i].delays[x] = last
                            start = t
                            last = start + 1
                        }
                    }
                    for(x in start until last)
                        planets[i].delays[x] = last
                }
            }
            val q = PriorityQueue<State>()
            q.add(State(0, 0))
            planets[0].minTime = 0
            while(q.isNotEmpty()){
                val s = q.poll()
                if(s.idPlanet == N - 1)break
                if(planets[s.idPlanet].minTime < s.time)continue

                for(e in planets[s.idPlanet].routes){
                    var timeNow = s.time
                    if(planets[s.idPlanet].delays.containsKey(timeNow))
                        timeNow = planets[s.idPlanet].delays[timeNow]!!
                    timeNow += e.cost
                    if(e.target.minTime > timeNow){
                        e.target.minTime = timeNow
                        q.add(State(e.target.id, timeNow))
                    }
                }
            }
            var ans = planets[N - 1].minTime
            if(ans == Int.MAX_VALUE)ans = -1
            println(ans)
        }
    }

