class Fenwick(val n : Int){
    var t = IntArray(n + 1);

    fun upd(pos : Int, v : Int){
        var idx = pos;
        while(idx <= n){
            t[idx] = max(t[idx], v);
            idx += idx and (-idx);
        }
    }

    fun pref(pos : Int): Int{
        var ans = 0;
        var idx = pos;
        while(idx != 0){
            ans = max(ans, t[idx]);
            idx -= idx and (-idx);
        }
        return ans;
    }
}

