fun c(n: Int, k: Int): Sequence<Long> {
    return when {
        k < 0 || k > n -> emptySequence()
        n == 0 -> sequenceOf(0)
        else -> sequence {
            yieldAll(c(n - 1, k).map {it.shl(1)})
            yieldAll(c(n - 1, k - 1).map {it.shl(1) + 1})
        }
    }
}

