            }
        }
    }

}

fn solve<R: std::io::BufRead, W: std::io::Write>(scanner: &mut Scanner<R>, writer: &mut W) {
    let n: usize = scanner.scan();
    let p1: i64 = scanner.scan();
    let p2: i64 = scanner.scan();
    let p3: i64 = scanner.scan();
    let t1: i64 = scanner.scan();
    let t2: i64 = scanner.scan();
    let l: i64 = scanner.scan();
    let r: i64 = scanner.scan();
    let mut result: i64 = (r - l) * p1;
    let mut last: i64 = r;
    for _ in 1..n {
        let l: i64 = scanner.scan();
        let r: i64 = scanner.scan();
        result += (r - l) * p1 + (l - last).max(0) * p1 + (l - last - t1).max(0) * (p2 - p1)
            + (l - last - t1 - t2).max(0) * (p3 - p2);
        last = r;
    }
    writeln!(writer, "{}", result).unwrap();
}

