fn all_same(s: &String) -> bool {
    if s.len() <= 1 {
        return true;
    }
    let fch: char = s.chars().next().unwrap();
    for ch in s.chars().skip(1) {
        if ch != fch {
            return false;
        }
    }
    true
}
fn all_diff(s: &String) -> bool {
    if s.len() <= 1 {
        return true;
    }
    let chars = s.chars().collect::<Vec<char>>();
    for i in 0..s.len() - 1 {
        if chars[i] == chars[i + 1] {
            return false;
        }
    }
    true
}
