fn main() {
    let buf = &mut io::BufReader::new(io::stdin());
    let mut lines = Vec::new();
    let mut max_len = 0;
    loop {
        let mut line = String::new();
        let read_result = buf.read_line(&mut line);
        match read_result {
            Ok(0) => break,
            _ => {}
        }
        let text = line.trim();
        max_len = max_len.max(text.len());
        lines.push(text.to_owned());
    }
    let mut left_align = true;
    println!("{}", rep('*', max_len + 2));
    for l in lines {
        let spaces = max_len - l.len();
        if spaces % 2 == 0 {
            println!("*{}{}{}*", rep(' ', spaces/2), l, rep(' ', spaces/2));
        } else {
            if left_align {
                println!("*{}{}{}*", rep(' ', spaces/2), l, rep(' ', spaces/2 + 1));
            } else {
                println!("*{}{}{}*", rep(' ', spaces/2 + 1), l, rep(' ', spaces/2));
            }
            left_align = !left_align;
        }
    }
    println!("{}", rep('*', max_len + 2));
}

