    let a: Vec<i32> = (0..n).map(|_| scanner.scan()).collect();
    let mut len = 1;
    let mut result = 1usize;
    for i in 1..n {
        if a[i] == a[i - 1] {
            len += 1;
        } else {
            len = 1;
        }
        result += len;
    }
    writeln!(writer, "{}", result).unwrap();
