    n7: usize,
}
impl LuckyNum{
    fn new(n4: usize, n7: usize) -> LuckyNum{
        LuckyNum { n4, n7 }
    }
    fn len(&self) -> usize{
        self.n4 + self.n7
    }
    fn digit_sum(&self) -> usize{
        self.n4 * 4 + self.n7 * 7
    }
    fn less_than(&self, other: &LuckyNum) -> bool{
        if self.len() < other.len(){
            true
        }
        else if self.len() > other.len(){
            false
        }
        else{
            self.n4 > other.n4
        }
    }
    fn to_string(&self) -> String{
        let mut res = "4".repeat(self.n4);
        res.push_str("7".repeat(self.n7).as_str());
        res
    }
}
