    for n4 in 0..=n/4{
        let n7 = (n - n4 * 4) / 7;
        let lucky_num = LuckyNum::new(n4, n7);
        if lucky_num.digit_sum() == n && lucky_num.less_than(&ans){
            ans = lucky_num;
        }
    }
    if ans.digit_sum() == n{
