#[derive(Debug)]
struct Edge {
    from: usize,
    to: usize,
    price: usize,
}

#[derive(Debug)]
struct City {
    id: usize,
    roads: Vec<Road>,
}

#[derive(Debug)]
struct Road {
    to: usize,
    out: bool,
    price: usize,
}

fn main() {
    let stdin = std::io::stdin();

    let cities_count: usize = {
        let mut buf = String::new();
        stdin.read_line(&mut buf).unwrap();
        let mut iter = buf.trim_end().split_whitespace();
        iter.next().unwrap().parse().unwrap()
    };

    let edges: Vec<Edge> = {
        let mut edges = Vec::with_capacity(cities_count);
        for _ in 0..cities_count {
            let mut buf = String::new();
            stdin.read_line(&mut buf).unwrap();
            let mut iter = buf.trim_end().split_whitespace();
            let from:  usize = iter.next().unwrap().parse().unwrap();
            let to:    usize = iter.next().unwrap().parse().unwrap();
            let price: usize = iter.next().unwrap().parse().unwrap();
            edges.push(Edge { from, to, price });
        }
        edges
    };

    let total_price: usize = edges.iter().map(|edge| edge.price).sum();

    let cities: Vec<City> = {
        let mut cities = Vec::with_capacity(cities_count);
        for index in 1..=cities_count {
            cities.push(City { id: index, roads: Vec::with_capacity(2) });
        }
        for edge in edges {
            cities[edge.from - 1].roads.push(Road {
                to: edge.to,
                out: true,
                price: edge.price,
            });
            cities[edge.to - 1].roads.push(Road {
                to: edge.from,
                out: false,
                price: edge.price,
            });
        }
        cities
    };

    let price: usize = {
        let mut price = 0;

        let start_id = 1;
        let mut current_id = start_id;
        let mut next_id = cities[current_id - 1].roads[0].to;
        let dir = cities[current_id - 1].roads[0].out;

        loop {
            let current_road = cities[current_id - 1]
                .roads
                .iter()
                .filter(|road| road.to == next_id)
                .next()
                .unwrap();
            let next_road = cities[next_id - 1]
                .roads
                .iter()
                .filter(|road| road.to != current_id)
                .next()
                .unwrap();

            if current_road.out != dir {
                price += current_road.price;
            }

            current_id = current_road.to;
            next_id = next_road.to;
            if current_id == start_id { break }
        }

        price
    };

    println!("{}", std::cmp::min(price, total_price - price));
}

