    let mut right = 100_005;
    while right - left > 1 {
        let n = (left + right) >> 1;

        let mut it = 0;
        let mut nodes = (0..n).collect();
        if !build(&s, &mut it, &mut nodes, 0, n) {
            right = n;
        } else {
            if it == s.len() {
