fn solve(ws: &mut std::str::SplitWhitespace) {
    let n: usize = ws.next().unwrap().parse().unwrap();
    let points: Vec<(i32, i32)> = (0..n)
        .map(|_| {
            (
                ws.next().unwrap().parse().unwrap(),
                ws.next().unwrap().parse().unwrap(),
            )
        })
        .collect();

    let mut visited = vec![false; n];
    let mut q = std::collections::VecDeque::new();

    let mut ans = 0;
    for i in 0..n {
        if visited[i] {
            continue;
        }
        q.push_back(points[i]);
        visited[i] = true;
        while !q.is_empty() {
            let p = q.pop_front().unwrap();
            for j in 0..n {
                if points[j] == p {
                    visited[j] = true;
                    continue;
                }
                if visited[j] {
                    continue;
                }
                if p.0 == points[j].0 {
                    q.push_back(points[j]);
                } else if p.1 == points[j].1 {
                    q.push_back(points[j]);
                }
            }
        }
        ans += 1;
    }

    println!("{}", ans - 1);
}

