use std::io::{self, BufRead};

struct Problem {
    flags: String,
    seq1: String,
    seq2: String,
}

fn reverse_ascii_str(s: &mut str) {
    unsafe {
        let bytes = s.as_bytes_mut();
        bytes.reverse();
    }
}

fn trim_end_mut(s: &mut String) {
    s.truncate(s.trim_end().len());
}

fn consecutive_subsequences(s: &str, sub1: &str, sub2: &str) -> bool {
    if let Some((i, _)) = s.match_indices(sub1).next() {
        if let Some((j, _)) = s.rmatch_indices(sub2).next() {
            if i + sub1.len() <= j {
                return true
            }
        }
    }
    false
}

fn parse_problem<B: BufRead>(mut input: B) -> io::Result<Problem> {
    let mut prob = Problem { flags: String::new(),
                             seq1: String::new(),
                             seq2:String::new() };
    input.read_line(&mut prob.flags)?;
    input.read_line(&mut prob.seq1)?;
    input.read_line(&mut prob.seq2)?;
    trim_end_mut(&mut prob.flags);
    trim_end_mut(&mut prob.seq1);
    trim_end_mut(&mut prob.seq2);
    Ok(prob)
}



fn main() -> io::Result<()> {
    let mut problem = parse_problem(io::stdin().lock())?;
    let forward_possible = consecutive_subsequences(&mut problem.flags,
                                                    &mut problem.seq1,
                                                    &mut problem.seq2);
    reverse_ascii_str(&mut problem.flags);
    let backward_possible = consecutive_subsequences(&mut problem.flags,
                                                     &mut problem.seq1,
                                                     &mut problem.seq2);
    let out = match (forward_possible, backward_possible) {
        (true, true) => "both",
        (true, false) => "forward",
        (false, true) => "backward",
        (false, false) => "fantasy",
    };
    println!("{}", out);
    Ok(())
}

