trait IterCopyExt<'a, T>: IntoIterator<Item = &'a T> + Sized
where
    T: 'a + Copy,
{
    fn citer(self) -> std::iter::Copied<Self::IntoIter> {
        self.into_iter().copied()
    }
}

impl<'a, T, I> IterCopyExt<'a, T> for I
where
    I: IntoIterator<Item = &'a T>,
    T: 'a + Copy,
{
}

trait IteratorExt: Iterator + Sized {
    fn sorted(self) -> <std::vec::Vec<Self::Item> as IntoIterator>::IntoIter
    where
        Self::Item: std::cmp::Ord,
    {
        let mut v = self.collect::<Vec<_>>();
        v.sort();
        v.into_iter()
    }

    fn sorted_by<F>(self, f: F) -> <std::vec::Vec<Self::Item> as IntoIterator>::IntoIter
    where
        F: FnMut(&Self::Item, &Self::Item) -> std::cmp::Ordering,
    {
        let mut v = self.collect::<Vec<_>>();
        v.sort_by(f);
        v.into_iter()
    }

    fn sorted_by_key<F, K>(self, f: F) -> <std::vec::Vec<Self::Item> as IntoIterator>::IntoIter
    where
        F: FnMut(&Self::Item) -> K,
        K: std::cmp::Ord,
    {
        let mut v = self.collect::<Vec<_>>();
        v.sort_by_key(f);
        v.into_iter()
    }

    fn join(self, delim: &str) -> String
    where
        Self::Item: ToString,
    {
        self.enumerate().fold(String::new(), |s, (i, t)| {
            if i == 0 {
                s + &t.to_string()
            } else {
                s + delim + &t.to_string()
            }
        })
    }
}

impl<I> IteratorExt for I where I: Iterator {}

