fn solve(input: &mut Input, _test_case: usize) {
    let n = input.read::<usize>();
    let s = input.read_string().bytes().map(|b| b - b'a').collect_vec();

    let mut sp = s.iter().copied().enumerate().collect_vec();

    let mut ans = vec![0; n];

    let mut count = 0;
    while !sp.is_empty() {
        count += 1;
        let mut removed = vec![false; sp.len()];
        let mut last = 0;
        for (idx, &(i, c)) in sp.iter().enumerate() {
            if c < last {
                continue;
            }
            last = c;
            ans[i] = count;
            removed[idx] = true;
        }
        sp = sp
            .into_iter()
            .enumerate()
            .filter_map(|(idx, e)| (!removed[idx]).then_some(e))
            .collect();
    }

    out_line!(count);
    out_line!(ans);
}

pub(crate) fn run(mut input: Input) -> bool {
    solve(&mut input, 1);
    output().flush();
    input.skip_whitespace();
    input.peek().is_none()
}

#[allow(unused)]
pub fn submit() -> bool {
    let io = TaskIoSettings {
        is_interactive: false,
        input: TaskIoType::Std,
        output: TaskIoType::Std,
    };

    run_task(io, run)
}

