fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut lines = input.lines();
    let params: Vec<usize> = lines.next().unwrap().split_whitespace().map(|x| x.parse().unwrap()).collect();
    let n = params[0];
    let k = params[1];

    let energy: Vec<f64> = lines.next().unwrap().split_whitespace().map(|x| x.parse().unwrap()).collect();

    let mut low = 0.0;
    let mut high = 1000.0;

    for _ in 0..100 {
        let mid = (low + high) / 2.0;
        let mut total_loss = 0.0;

        for i in 0..n {
            if energy[i] > mid {
                total_loss += (energy[i] - mid) * (1.0 - (k as f64) / 100.0);
            } else {
                total_loss -= (mid - energy[i]);
            }
        }

        if total_loss > 0.0 {
            low = mid;
        } else {
            high = mid;
        }
    }

    println!("{:.9}", low);
}

