struct Scanner<R> {
    reader: R,
    line: Vec<u8>,
    ptr: usize

}

impl<R: std::io::BufRead> Scanner<R> {
    fn new(reader: R) -> Self {
        Self{reader, line: vec![], ptr: 0}
    }

    fn scan<T: std::str::FromStr>(&mut self) -> T {
        loop {
            while self.ptr < self.line.len() && self.line[self.ptr].is_ascii_whitespace() {
                self.ptr += 1;
            }
            if self.ptr != self.line.len() {
                let start = self.ptr;
                while self.ptr < self.line.len() && !self.line[self.ptr].is_ascii_whitespace() {
                    self.ptr += 1;
                }
                return std::str::from_utf8(&self.line[start..self.ptr]).unwrap().parse().ok().
                    expect("parse error");
            }
            self.line.clear();
            self.reader.read_until(b'\n', &mut self.line).expect("read error");
            self.ptr = 0;
        }
    }

}

fn fill(mask: usize, set: &Vec<bool>, maxs: &mut Vec<u32>) -> u32 {
    if maxs[mask] != u32::MAX {
        return maxs[mask];
    }
    maxs[mask] = if set[mask] {mask.count_ones()} else {0};
    let mut tmp = mask;
    while tmp != 0 {
        let bit = (tmp & (tmp - 1)) ^ tmp;
        tmp ^= bit;
        let next = mask ^ bit;
        fill(next, set, maxs);
        maxs[mask] = maxs[mask].max(maxs[next]);
    }
    return maxs[mask];
}

fn solve<R: std::io::BufRead, W: std::io::Write>(scanner: &mut Scanner<R>, writer: &mut W) {
    let s: Vec<usize> = scanner.scan::<String>().bytes().map(|c| 1usize << (c - b'a')).collect();
    let masks = 1 << 20;
    let mut set = vec![false; masks];
    let n = s.len();
    for i in 0..n {
        let mut mask = 0;
        for j in i..n {
            if mask & s[j] != 0 {
                break;
            }
            mask |= s[j];
            set[mask] = true;
        }
    }
    let mut maxs = vec![u32::MAX; masks];
    fill(masks - 1, &set, &mut maxs);
    let mut result = 0;
    for mask in 0..masks {
        if !set[mask] {
            continue;
        }
        result = result.max(mask.count_ones() + maxs[!mask & (masks - 1)]);
    }
    writeln!(writer, "{}", result).unwrap();
}

