        costs: [[usize; n]; 3],
    };
    
    let mut children = vec![vec![]; n];
    for _ in 1..n {
        input!{ u: usize1, v: usize1 };
        if children[u].len() >= 2 || children[v].len() >= 2 {
            println!("-1");
            return;
        }
        children[u].push(v);
        children[v].push(u);
    }
    
    for i in 0..n {
        if children[i].len() == 1 {
            let line = makeline(&children, i);
            let mut min = usize::MAX;
            let mut scheme = [0; 3];
            for pat in [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]] {
                let mut cost = 0;
                for (i, &idx) in line.iter().enumerate() {
                    cost += costs[pat[i % 3]][idx];
                }
                if cost < min {
                    min = cost;
                    scheme = pat;
                }
            }
            let mut painted = vec![0; n];
            for (i, &idx) in line.iter().enumerate() {
                painted[idx] = scheme[i % 3];
            }
            println!("{min}");
            for c in painted {
                print!("{} ", c + 1);
            }
            return;
        }
    }
}

fn makeline(tree: &[Vec<usize>], root: usize) -> Vec<usize> {
    let n = tree.len();
    let mut line = Vec::with_capacity(n);
    let (mut cur, mut fa) = (tree[root][0], root);
    line.push(fa);
    line.push(cur);
    
    while line.len() < n {
        let next = if tree[cur][0] == fa { tree[cur][1] } else { tree[cur][0] };
        line.push(next);
        fa = cur;
        cur = next;
    }
    
    line
}

mod io {
    use std::cell::RefCell;
    use std::io::*;

    std::thread_local! {
        pub static STDIN: RefCell<Stdin> = RefCell::new(stdin());
        pub static STDOUT: RefCell<BufWriter<Stdout>> = RefCell::new(BufWriter::new(stdout()));
    }

    #[macro_export]
    macro_rules! input {
        () => {};
        (mut $var:ident: $t:tt, $($rest:tt)*) => {
            let mut $var = __input_inner!($t);
            input!($($rest)*)
        };
        ($var:ident: $t:tt, $($rest:tt)*) => {
            let $var = __input_inner!($t);
            input!($($rest)*)
        };
        (mut $var:ident: $t:tt) => {
            let mut $var = __input_inner!($t);
        };
        ($var:ident: $t:tt) => {
            let $var = __input_inner!($t);
        };
    }

    #[macro_export]
    macro_rules! __input_inner {
        (($($t:tt),*)) => {
            ($(__input_inner!($t)),*)
        };
        ([$t:tt; $n:expr]) => {
            (0..$n).map(|_| __input_inner!($t)).collect::<Vec<_>>()
        };
        ([$t:tt]) => {{
            let n = __input_inner!(usize);
            (0..n).map(|_| __input_inner!($t)).collect::<Vec<_>>()
        }};
        (chars) => {
            __input_inner!(String).chars().collect::<Vec<_>>()
        };
        (bytes) => {
            __input_inner!(String).into_bytes()
        };
        (usize1) => {
            __input_inner!(usize) - 1
        };
        ($t:ty) => {
            $crate::io::STDIN.with(|r| {
                use std::io::BufRead;
                let r = r.borrow_mut();
                let mut r = r.lock();
                let mut s = vec![];
                loop {
                    let buf = r.fill_buf().unwrap();
                    if buf.is_empty() {
                        break;
                    }
                    if let Some(i) = buf.iter().position(u8::is_ascii_whitespace) {
                        s.extend_from_slice(&buf[..i]);
                        r.consume(i + 1);
                        if !s.is_empty() {
                            break;
                        }
                    } else {
                        s.extend_from_slice(buf);
                        let n = buf.len();
                        r.consume(n);
                    }
                }
                std::str::from_utf8(&s).unwrap().parse::<$t>().unwrap()
            })
        };
    }

    #[macro_export]
    macro_rules! println {
        () => {
            $crate::io::STDOUT.with(|w| {
                use std::io::Write;
                std::writeln!(w.borrow_mut()).unwrap()
            })
        };
        ($($arg:tt)*) => {
            $crate::io::STDOUT.with(|w| {
                use std::io::Write;
                std::writeln!(w.borrow_mut(), $($arg)*).unwrap()
            })
        };
    }

    #[macro_export]
    macro_rules! print {
        ($($arg:tt)*) => {
            $crate::io::STDOUT.with(|w| {
                use std::io::Write;
                std::write!(w.borrow_mut(), $($arg)*).unwrap()
            })
        };
    }

    #[macro_export]
    macro_rules! flush {
        () => {
            $crate::io::STDOUT.with(|w| {
                use std::io::Write;
                w.borrow_mut().flush().unwrap()
            })
        };
    }
}

fn main() {
    input!{
        n: usize,
        k: usize,
        mut a: [usize; n],
    };
    a.sort_unstable();
    let sum = a.iter().sum::<usize>();

    let check = |max: usize| {
        let mut l = 0;
        let (mut lsum, mut rsum) = (0, sum);
        for (r, &x) in a.iter().enumerate() {
            rsum -= x;
            while x - a[l] > max {
                lsum += a[l];
                l += 1;
            }
            let op = if l == 0 { 0 } else { l * (x - max) - lsum } + rsum - (n - 1 - r) * x;
            if op <= k {
                return true;
            }
        }

        let mut r = n - 1;
        lsum = sum;
        rsum = 0;
        for (l, &x) in a.iter().enumerate().rev() {
            lsum -= x;
            while a[r] - x > max {
                rsum += a[r];
                r -= 1;
            }
            let op = x * l - lsum + rsum - (n - 1 - r) * (x + max);
            if op <= k {
                return true;
            }
        }
        false
    };

    let (mut low, mut high) = (0, a[n - 1] - a[0]);
    while low < high {
        let mid = (high - low)/2 + low;
        if check(mid) {
            high = mid;
        } else {
            low = mid + 1;
        }
    }

    println!("{}", high);
}


