use std::io::Write;

fn mod_pow(r: u128, mut n: u128, p: u128) -> u128 {
    let mut t = 1;
    let mut s = r;
    while n > 0 {
        if n & 1 == 1 {
            t = t * s % p;
        }
        s = s * s % p;
        n >>= 1;
    }
    t
}

fn run() {
    input! {
        n: usize,
        s: chars,
        q: usize,
        ask: [(usize1, usize1, usize); q],
    }
    const MOD: u128 = 4611686018427194327;
    let rad = 3;
    let mut pow = vec![1; n + 1];
    for i in 1..=n {
        pow[i] = pow[i - 1] * rad % MOD;
    }
    let inv = mod_pow(rad, MOD - 2, MOD);
    type T = (u128, usize, bool, bool);// ハッシュ、長さ、先頭1, 最後1
    let fold = |a: T, b: T| -> T {
        if a.1 == 0 {
            return b;
        }
        if b.1 == 0 {
            return a;
        }
        if a.3 && b.2 {
            let mut val = a.0;
            val = (val + MOD - 2 * pow[a.1 - 1] % MOD) % MOD;
            val = (val + pow[a.1 - 1] * (b.0 + MOD - 2) % MOD * inv % MOD) % MOD;
            let len = a.1 + b.1 - 2;
            return match (a.1 == 1, b.1 == 1) {
                (true, true) => (0, 0, false, false),
                (true, false) => (val, len, false, b.3),
                (false, true) => (val, len, a.2, false),
                (false, false) => (val, len, a.2, b.3),
            };
        }
        let val = (a.0 + pow[a.1] * b.0 % MOD) % MOD;
        let len = a.1 + b.1;
        (val, len, a.2, b.3)
    };
    let mut seg = segment_tree::PURQ::new(n, (0, 0, false, false), fold);
    for i in 0..n {
        if s[i] == '1' {
            seg.update_tmp(i, (2, 1, true, true));
        } else {
            seg.update_tmp(i, (1, 1, false, false));
        }
    }
    seg.update_all();
    let out = std::io::stdout();
    let mut out = std::io::BufWriter::new(out.lock());
    for (x, y, len) in ask {
        let p = seg.find(x, x + len);
        let q = seg.find(y, y + len);
        if p.0 == q.0 && p.1 == q.1 {
            writeln!(out, "Yes").ok();
        } else {
            writeln!(out, "No").ok();
        }
    }

}

