// 最大値は貪欲に割り当てれば良い？
// 2冪を均等に割り振る、割り振れなかったのは2冪でない列に突っ込む
// 2冪でない列を貪欲に割り当てる
// 小さい値を小さい値に割り振る感じ
// これでできないならNo
// できたら？
// 小さい列を解消して再割り当てができるかというのを順に続けるといいか
// 計算量？
// 全部1とかだと割り当ての回数がO(N)になる、辛い
// 割り当て可能かは単調なので二分探索

fn valid(beki: &[u64], b: &mut [u64]) -> bool {
    b.sort();
    let mut p = 0;
    for pow in beki.iter().rev() {
        if p < b.len() && *pow * 2 >= b[p] {
            p += 1;
        }
    }
    p == b.len()
}

fn run() {
    input! {
        n: usize,
        a: [u64; n],
    }
    let mut beki = vec![];
    let mut k = 0;
    while k < n && a[k] == 1 {
        beki.push(1);
        k += 1;
    }
    if k == 0 {
        println!("-1");
        return;
    }
    let mut pos = 0;
    let mut b = vec![];
    for a in a[k..].iter() {
        if *a == beki[pos] * 2 {
            beki[pos] *= 2;
            pos = (pos + 1) % beki.len();
        } else {
            pos = 0;
            if *a == beki[pos] * 2 {
                beki[pos] *= 2;
                pos = (pos + 1) % beki.len();
            } else {
                b.push(*a);
            }
        }
    }
    let (beki, b) = (beki, b);
    if !valid(&beki, &mut b.clone()) {
        println!("-1");
        return;
    }
    let mut ok = beki.len();
    let mut ng = 0;
    while ok - ng > 1 {
        let mid = (ok + ng) / 2;
        let mut b = b.clone();
        for p in beki[mid..].iter() {
            let mut k = 1;
            while k <= *p {
                b.push(k);
                k *= 2;
            }
        }
        if valid(&beki[..mid], &mut b) {
            ok = mid;
        } else {
            ng = mid;
        }
    }
    let mut s = String::new();
    for k in ok..=beki.len() {
        s.push_str(&format!("{} ", k));
    }
    s.pop();
    println!("{}", s);
}

fn main() {
    run();
}

