use modint::*;
type M = ModInt<Mod>;

fn run() {
    input! {
        n: usize,
        p: [(i32, i32); n],
    }
    let mut x = vec![];
    let mut y = vec![];
    for p in p.iter() {
        x.push(p.0);
        y.push(p.1);
    }
    x.sort();
    x.dedup();
    y.sort();
    y.dedup();
    let len = x.len() + y.len();
    let mut dsu = DSU::new(len);
    let mut cnt = vec![0; len];
    for &(a, b) in p.iter() {
        let a = x.binary_search(&a).unwrap();
        let b = y.binary_search(&b).unwrap() + x.len();
        if let Some((a, b)) = dsu.unite(a, b) {
            cnt[a] += cnt[b];
        }
        cnt[dsu.root(a)] += 1;
    }
    let mut ans = M::one();
    for i in 0..len {
        if i == dsu.root(i) {
            let size = dsu.size(i);
            if cnt[i] >= size {
                ans *= M::new(2).pow(size as u64);
            } else {
                ans *= M::new(2).pow(size as u64) - M::one();
            }
        }
    }
    println!("{}", ans);
}

