const MOD: i64 = 998244353;

fn inv(a: i64) -> i64 {
    pow(a, MOD - 2)
}

fn pow(a: i64, p: i64) -> i64 {
    let mut p = p;
    let mut aa = a;
    let mut ret = 1;
    while p >= 1 {
        if p & 1 == 1 {
            ret *= aa;
            ret %= MOD;
        }
        p >>= 1;
        aa = aa * aa % MOD;
    }
    ret
}

fn main() {
    input! {
        n: usize, m: usize,
        mut a: [i64; n],
        w: [i64; n]
    };

    let mut like_weight = 0;
    let mut dislike_weight = 0;
    for i in 0..n {
        if a[i] == 1 {
            like_weight += w[i];
        } else {
            dislike_weight += w[i];
        }
    }


    let GETA = 3100;
    let mut denom_pm = vec![0; GETA*2];
    for i in 0..GETA*2 {
        let w = i as i64 + like_weight + dislike_weight;
        denom_pm[i] = ifv!(w >= GETA as i64, inv(w-GETA as i64), 0);
    }
    let mut quot = |l: usize, d: usize, num: i64| ifv!(num <= 0, 0, num * denom_pm[GETA+l-d] % MOD);

    let mut dp = dvec!(0; 2, m+1, m+1);
    for i in 0..m+1 {
        dp[0][i][m-i] = 1;
        dp[1][i][m-i] = 1;
    }
    for i in (0..m+1).rev() {
        for j in (0..m+1).rev() {
            if i+j >= m {
                continue;
            }
            let mut total0 = 0;
            let mut total1 = 0;

            if i+1 <= m {
                total0 += dp[0][i+1][j] * quot(i, j, like_weight+(i as i64)+1);
                total1 += dp[1][i+1][j] * quot(i, j, like_weight+(i as i64));
            }
            if j+1 <= m {
                total0 += dp[0][i][j+1] * quot(i, j, dislike_weight-(j as i64));
                total1 += dp[1][i][j+1] * quot(i, j, dislike_weight-(j as i64)-1);
            }
            dp[0][i][j] = total0 % MOD;
            dp[1][i][j] = total1 % MOD;
        }
    }

    let out = stdout();
    let mut out = BufWriter::new(out.lock());
    for i in 0..n {
        if a[i] == 1 {
            writeln!(out, "{}", dp[0][0][0] * w[i] % MOD);
        } else {
            writeln!(out, "{}", dp[1][0][0] * w[i] % MOD);
        }
    }
}

