        }else{
            con[(-x - 1) as usize] += 1;
            cons += 1;
        }
    }
    let mut candidates = vec![false; n];
    let mut single = false;
    let mut more = false;
    for i in 0..n {
        if pro[i] + cons - con[i] == m {
            more = single;
            single = true;
            candidates[i] = true;
        }
    }
    for x in a {
        if x > 0 {
            if candidates[(x - 1) as usize] {
                if single && !more {
                    writeln!(writer, "Truth").unwrap();
                }else{
                    writeln!(writer, "Not defined").unwrap();
                }
            }else{
                writeln!(writer, "Lie").unwrap();
            }
        }else{
            if !candidates[(-x - 1) as usize] {
                writeln!(writer, "Truth").unwrap();
            }else{
                if single && !more {
                    writeln!(writer, "Lie").unwrap();
                }else{
                    writeln!(writer, "Not defined").unwrap();
                }
            }
        }
    }
}

