              xss[s][f] += xss[s][f | 1 << e];
              xss[s][f | 1 << e] = tmp;
            }
          }
        }
        foreach (f; 0 .. 1 << (M / 2)) {
          ans[s + popcnt(f)] += xss[s][f];
        }
      }
      
