const int MAX = 100005;
const int MOD = 1000000007;
int n;
long x;
long[MAX] a;
long[long] count;
 
void main() {
    readf(" %s %s", n, x);
    foreach(i; 0..n) readf(" %s", a[i]);
 
    long totalSum = sum(a[0..n]);
    foreach(i; 0..n) a[i] = totalSum - a[i];
    foreach(i; 0..n) count[a[i]]++;
    auto heap = heapify!"a > b"(count.keys);

    long result = 0;
    do {
        auto value = heap.front;
        heap.popFront();

        auto y = count[value];
        auto k = 0;
        while (y % x == 0) {
            y /= x;
            k++;
        }

        if (k == 0) {
            result = value;
            break;
        }

        auto next = value + k;
        if (next !in count) {
            heap.insert(next);
        }
        count[next] += y;
    } while(!heap.empty);

    writeln(power(min(result, totalSum)));
}
 
long power(long m) {
    if (m == 0) return 1;
    if (m == 1) return x % MOD; 
    auto v = power(m/2);
    if (m % 2 == 0) {
        return (v * v) % MOD;
    } else {
        return (((v * v) % MOD) * x) % MOD;
    }
}

