    for (; ; ) {
      const numCases = readInt();
      foreach (caseId; 0 .. numCases) {
        const X1 = readLong() - 1;
        const Y1 = readLong() - 1;
        const X2 = readLong();
        const Y2 = readLong();
        const K = readLong();
        Mint ans;
        ans += solve(X1, Y1, K);
        ans -= solve(X1, Y2, K);
        ans -= solve(X2, Y1, K);
        ans += solve(X2, Y2, K);
        writeln(ans);
      }
    }
  } catch (EOFException e) {
  }
}

