use List::Util qw(min);

sub find {
    my ($x, $parent) = @_;
    if ($parent->[$x] != $x) {
        $parent->[$x] = find($parent->[$x], $parent);
    }
    return $parent->[$x];
}

sub union {
    my ($x, $y, $parent, $rank) = @_;
    my $px = find($x, $parent);
    my $py = find($y, $parent);
    if ($px != $py) {
        if ($rank->[$px] > $rank->[$py]) {
            $parent->[$py] = $px;
        } else {
            $parent->[$px] = $py;
            if ($rank->[$px] == $rank->[$py]) {
                $rank->[$py]++;
            }
        }
    }
}

