# Function to check if a point is inside a triangle
sub is_inside_triangle {
    my ($p, $p1, $p2, $p3) = @_;
    my $d1 = ($p1->[0] - $p->[0]) * ($p2->[1] - $p1->[1]) - ($p2->[0] - $p1->[0]) * ($p1->[1] - $p->[1]);
    my $d2 = ($p2->[0] - $p->[0]) * ($p3->[1] - $p2->[1]) - ($p3->[0] - $p2->[0]) * ($p2->[1] - $p->[1]);
    my $d3 = ($p3->[0] - $p->[0]) * ($p1->[1] - $p3->[1]) - ($p1->[0] - $p3->[0]) * ($p3->[1] - $p->[1]);
    return ($d1 >= 0 && $d2 >= 0 && $d3 >= 0) || ($d1 <= 0 && $d2 <= 0 && $d3 <= 0);
}

# Count the number of distinct triangles
my $count = 0;
for my $i (0..$N-1) {
    for my $j ($i+1..$N-1) {
        for my $k ($j+1..$N-1) {
            my $triangle = [$red_points[$i], $red_points[$j], $red_points[$k]];
            my $is_valid = 1;
            for my $blue_point (@blue_points) {
                if (is_inside_triangle($blue_point, @$triangle)) {
                    $is_valid = 0;
                    last;
                }
            }
            $count++ if $is_valid;
        }
    }
}

# Print the result
print $count;

