procedure Add(x : longint);
begin
 while x <= n do
 begin
  inc(t[x]);
  x:=x or (x - 1) + 1;
 end;
end;

function count(x : longint) : longint;
var
res : longint;
begin
 res:=0;
 while x > 0 do
 begin
  res:=res + t[x];
  x:=x and (x - 1);
 end;
 count:=res;
end;

procedure SortPoint(l,r : longint);
var
i,j,id,x,y : longint;
tmp : pair;
begin
 i:=l;
 j:=r;
 id:=l + random(r - l + 1);
 x:=p[id].r; y:=p[id].l;
 repeat
  while (x > p[i].r) or (x = p[i].r) and (y > p[i].l) do inc(i);
  while (x < p[j].r) or (x = p[j].r) and (y < p[j].l) do dec(j);
  if i <= j then
  begin
   tmp:=p[i]; p[i]:=p[j]; p[j]:=tmp;
   inc(i);dec(j);
  end;
 until i > j;
 if i < r then SortPoint(i,r);
 if l < j then SortPoint(l,j);
end;

procedure SortQuery(l,r : longint);
var
i,j,id,x,y : longint;
tmp : query;
begin
 i:=l;
 j:=r;
 id:=l + random(r - l + 1);
 x:=q[id].rr; y:=q[id].ll;
 repeat
  while (x > q[i].rr) or (x = q[i].rr) and (y > q[i].ll) do inc(i);
  while (x < q[j].rr) or (x = q[j].rr) and (y < q[j].ll) do dec(j);
  if i <= j then
  begin
   tmp:=q[i]; q[i]:=q[j]; q[j]:=tmp;
   inc(i);dec(j);
  end;
 until i > j;
 if i < r then SortQuery(i,r);
 if l < j then SortQuery(l,j);
end;

begin
 //reset (input,'input.txt');
 //rewrite (output,'output.txt');
 randomize;
 readln(n,m);
 fillchar(b,sizeof(b),0);
 for i:=1 to n do
 begin
  read(x);
  b[x]:=i;
 end;
 readln;
 for i:=1 to m do
 begin
  readln(q[i].ll,q[i].rr);
  q[i].id:=i;
  q[i].ans:=0;
 end;

