var
  t:    tr;
  n, i: integer;
  a, c: array[1..100000] of integer;

  function get_max(t: tr): integer;
  begin
    if t = nil then
      Result := 0
    else
      Result := t^.max;
  end;

  procedure update_max(t: tr);
  var
    a: integer;
  begin
    if t <> nil then
    begin
      if get_max(t^.l) < get_max(t^.r) then
        a := get_max(t^.r)
      else
        a := get_max(t^.l);
      if a < t^.a then
        a    := t^.a;
      t^.max := a;
    end;
  end;

  function get_cnt(t: tr): integer;
  begin
    if t = nil then
      Result := 0
    else
      Result := t^.cnt;
  end;

  procedure update_cnt(t: tr);
  begin
    if t <> nil then
      t^.cnt := get_cnt(t^.l) + get_cnt(t^.r) + 1;
  end;

  function get_pos(a, c: integer; t: tr): integer;
  var
    place: integer;
  begin
    place := 0;
    while t <> nil do
    begin
      if (get_cnt(t^.l) > c) or (get_max(t^.l) > a) then
      begin
        t := t^.l;
        continue;
      end;
      Dec(c, get_cnt(t^.l));
      Inc(place, (get_cnt(t^.l)));
      if (c = 0) or (t^.a > a) then
        break;
      Dec(c);
      Inc(place);
      t := t^.r;
    end;
    Result := place;
  end;

  procedure split(t:tr;var l, r: tr; x: integer);
  begin
    if t = nil then
    begin
      l := nil;
      r := nil;
      exit;
    end;
    if get_cnt(t^.l) < x then
    begin
      l := t;
      split(t^.r, l^.r, r, x - get_cnt(t^.l) - 1);
    end
    else
    begin
      r := t;
      split(t^.l, l, r^.l, x);
    end;
    update_cnt(t);
    update_max(t);
    update_cnt(l);
    update_max(l);
    update_cnt(r);
    update_max(r);
    if l <> nil then
    begin
      assert(l^.l <> l);
      assert(l^.r <> l);
    end;
    if r <> nil then
    begin
      assert(r^.l <> r);
      assert(r^.r <> r);
    end;
  end;

  procedure merge(l,r:tr;var t: tr);
  begin
    if l = nil then
    begin
      t := r;
      update_cnt(t);
      update_max(t);
      exit;
    end;
    if r = nil then
    begin
      t := l;
      update_cnt(t);
      update_max(t);
      exit;
    end;
    if l^.y < r^.y then
    begin
      merge(l^.r, r, t);
      l^.r := t;
      t    := l;
      assert(t^.l <> t);
      assert(t^.r <> t);
    end
    else
    begin
      merge(l, r^.l, t);
      r^.l := t;
      t    := r;
      assert(t^.l <> t);
      assert(t^.r <> t);
    end;
    update_cnt(t);
    update_max(t);
  end;

  procedure add(var t: tr; a, y, c, numb: integer);
  var
    p, l, r, v: tr;
    pos: integer;
  begin
    pos := get_pos(a, c, t);
    new(p);
    p^.a    := a;
    p^.y    := y;
    p^.l    := nil;
    p^.r    := nil;
    p^.cnt  := 1;
    p^.max  := a;
    p^.numb := numb;
    split(t, l, r, pos);
    merge(l, p, v);
    merge(v, r, t);
    if t <> nil then
    begin
      assert(t^.l <> t);
      assert(t^.r <> t);
    end;
  end;

  procedure dfs(v: tr;h:integer);
  var i:integer;
  begin
    if v^.r <> nil then
      dfs(v^.r,h+1);
    //for i:=1 to h do
    //  write('+');
    Write(v^.numb,' ');
   // writeln(' ', v^.a , ' ', v^.max);
    if v^.l <> nil then
      dfs(v^.l,h+1);
  end;

