procedure findpath(x, y : int);
var
  rev : int;
begin
	while (x <> 0) do begin
		mn := min(mn, w[x]-f[x]);
		x := p[x];
	end;
	while (y <> 0) do begin
		if (y and 1 = 1) then rev := y + 1
		else rev := y - 1;
		f[y] := f[y] + mn;
		f[rev] := f[rev] - mn;
		y := p[y];
	end;
end;
procedure bfsflow;
var
  pos : int;
begin
	i := 1; j := 1;
	fillchar(used, sizeof(used), false);
	q[1] := 0; used[0] := true;
	while (i <= j) do begin
		pos := s[q[i]];
		while (pos <> 0) do begin
			if (not used[v[pos]]) and (w[pos]-f[pos] > 0) then begin
				inc(j);
				q[j] := v[pos];
				used[q[j]] := true;
				u[j] := pos;
				p[pos] := u[i];
				if (q[j] = 2*n*n+1) then begin
					findpath(pos, pos);
					exit;
				end;
			end;
			pos := next[pos];
		end;
		inc(i);
	end;
