{$R+Q+,I+}
{$apptype console}
Uses SysUtils,math;
Var
   dp:Array[0..50,0..50] of Int64;
   n,h,i,j:Integer;
   ans:Int64;
Function Solve(n,h:Integer):Int64;
Var v,h1,h2,k1,k2:Integer;
Begin
   If dp[n,h]<>-1 Then Begin
      Solve:=dp[n,h];
      Exit;
   End;
   If n=1 Then Begin
      If h=1 Then dp[n,h]:=1
             Else dp[n,h]:=0;
      Solve:=dp[n,h];
      Exit;
   End;
   If h=0 Then Begin
      dp[n,h]:=0;
      Solve:=dp[n,h];
      Exit;
   End;
   dp[n,h]:=0;
   For v:=1 To n Do Begin
      k1:=v-1;
      k2:=n-v;
      If v=1 Then Begin
         dp[n,h]:=dp[n,h]+Solve(n-1,h-1);
         Continue;
      End;
      If v=n Then Begin
         dp[n,h]:=dp[n,h]+Solve(n-1,h-1);
         Continue;
      End;
      For h1:=0 To min(k1,h-2) Do dp[n,h]:=dp[n,h]+Solve(k1,h1)*Solve(k2,h-1);
      For h2:=0 To min(k2,h-2) Do dp[n,h]:=dp[n,h]+Solve(k1,h-1)*Solve(k2,h2);
      dp[n,h]:=dp[n,h]+Solve(k1,h-1)*Solve(k2,h-1);
   End;
   Solve:=dp[n,h];
End;
Begin
   Read(n,h);
   For i:=0 To 50 Do
      For j:=0 To 50 Do dp[i,j]:=-1;
   ans:=0;
   For i:=h To n Do ans:=ans+Solve(n,i);
   Write(ans);
End.

